/**
 * Initial empty state markup for the AI Chat log.
 * Single source of truth for both the initial UI rendering and chat resets.
 */
export const AI_CHAT_EMPTY_HTML: string = `
              <div class="ai-chat-empty">
                <strong>Text / Image to 3D Mesh & Update</strong><br />
                Describe a 3D object, attach a reference image, or select a mesh in the scene to modify it with AI.
              </div>
`.trim();

/**
 * Generates the inner HTML structure for the Mesh Editor UI.
 * Compiled from src/mesheditor.ejs and decentralized tool views (src/tools/editor/*.ejs).
 * Used when mounting the editor programmatically into a container element
 * or inside the <mesh-editor> Web Component.
 */
export function getMeshEditorTemplate(): string {
  return "\n      <!-- Hidden file inputs -->\n      <input type=\"file\" id=\"modelFileInput\" class=\"hidden-input\" accept=\".glb,.gltf,.obj,.stl,.ply,.fbx,.babylon,.bin,.png,.jpg,.jpeg,.webp\" multiple />\n      <input type=\"file\" id=\"importFileInput\" class=\"hidden-input\" accept=\".glb,.gltf,.obj,.stl,.ply,.fbx,.babylon,.bin,.png,.jpg,.jpeg,.webp\" multiple />\n      <input type=\"file\" id=\"textureFileInput\" class=\"hidden-input\" accept=\"image/*\" />\n      <input type=\"file\" id=\"bumpFileInput\" class=\"hidden-input\" accept=\"image/*\" />\n      <input type=\"file\" id=\"aiImageFileInput\" class=\"hidden-input\" accept=\"image/*\" multiple />\n      <input type=\"file\" id=\"embedTextureFileInput\" class=\"hidden-input\" accept=\".png,.jpg,.jpeg,.webp,image/*\" multiple />\n      <input type=\"file\" id=\"embedAtlasFileInput\" class=\"hidden-input\" accept=\".png,.jpg,.jpeg,.webp,.json,.tps,.xml,image/*\" multiple />\n      <input type=\"file\" id=\"voxelAtlasFileInput\" class=\"hidden-input\" accept=\".png,.jpg,.jpeg,.webp,.json,.tps,.xml,image/*\" multiple />\n      <input type=\"file\" id=\"voxelJsonFileInput\" class=\"hidden-input\" accept=\".json\" />\n\n      <!-- Top Toolbar -->\n      <header id=\"top-toolbar\">\n        <div class=\"toolbar-brand\" title=\"Mesh Editor\">\n          <svg width=\"1024\" height=\"1024\" viewBox=\"0 0 1024 1024\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n  <defs>\n    <!-- Background Squircle Gradient (Obsidian / Dark Cyber Space) -->\n    <linearGradient id=\"bgGrad\" x1=\"512\" y1=\"80\" x2=\"512\" y2=\"944\" gradientUnits=\"userSpaceOnUse\">\n      <stop offset=\"0%\" stop-color=\"#121620\" />\n      <stop offset=\"40%\" stop-color=\"#0c0e14\" />\n      <stop offset=\"100%\" stop-color=\"#050608\" />\n    </linearGradient>\n\n    <!-- Squircle Border Subtle Metallic Rim -->\n    <linearGradient id=\"rimGrad\" x1=\"512\" y1=\"80\" x2=\"512\" y2=\"944\" gradientUnits=\"userSpaceOnUse\">\n      <stop offset=\"0%\" stop-color=\"#58a6ff\" stop-opacity=\"0.32\" />\n      <stop offset=\"50%\" stop-color=\"#1f6feb\" stop-opacity=\"0.22\" />\n      <stop offset=\"100%\" stop-color=\"#00f0ff\" stop-opacity=\"0.1\" />\n    </linearGradient>\n\n    <!-- Squircle Drop Shadow -->\n    <filter id=\"squircleShadow\" x=\"30\" y=\"40\" width=\"964\" height=\"964\" filterUnits=\"userSpaceOnUse\">\n      <feDropShadow dx=\"0\" dy=\"24\" stdDeviation=\"22\" flood-color=\"#000000\" flood-opacity=\"0.75\" />\n    </filter>\n\n    <!-- Neon Glow Filter for Outer Edges & Nodes -->\n    <filter id=\"neonGlow\" x=\"-25%\" y=\"-25%\" width=\"150%\" height=\"150%\">\n      <feGaussianBlur stdDeviation=\"10\" result=\"blur\" />\n      <feMerge>\n        <feMergeNode in=\"blur\" />\n        <feMergeNode in=\"blur\" />\n        <feMergeNode in=\"SourceGraphic\" />\n      </feMerge>\n    </filter>\n\n    <!-- Soft Bloom for Inner Core -->\n    <radialGradient id=\"ambientGlow\" cx=\"512\" cy=\"512\" r=\"380\" gradientUnits=\"userSpaceOnUse\">\n      <stop offset=\"0%\" stop-color=\"#1f6feb\" stop-opacity=\"0.36\" />\n      <stop offset=\"35%\" stop-color=\"#00d2ff\" stop-opacity=\"0.18\" />\n      <stop offset=\"70%\" stop-color=\"#090d16\" stop-opacity=\"0.05\" />\n      <stop offset=\"100%\" stop-color=\"#000000\" stop-opacity=\"0\" />\n    </radialGradient>\n\n    <!-- Edge Specular Highlight: Center Vertical Ridge -->\n    <linearGradient id=\"centerRidgeSpec\" x1=\"512\" y1=\"172\" x2=\"512\" y2=\"512\" gradientUnits=\"userSpaceOnUse\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\" stop-opacity=\"1\" />\n      <stop offset=\"20%\" stop-color=\"#a5f3fc\" stop-opacity=\"0.95\" />\n      <stop offset=\"70%\" stop-color=\"#38bdf8\" stop-opacity=\"0.65\" />\n      <stop offset=\"100%\" stop-color=\"#1f6feb\" stop-opacity=\"0.15\" />\n    </linearGradient>\n\n    <!-- Edge Specular Highlight: Top Left Edge -->\n    <linearGradient id=\"topLeftSpec\" x1=\"218\" y1=\"342\" x2=\"512\" y2=\"172\" gradientUnits=\"userSpaceOnUse\">\n      <stop offset=\"0%\" stop-color=\"#38bdf8\" stop-opacity=\"0.4\" />\n      <stop offset=\"65%\" stop-color=\"#e0f2fe\" stop-opacity=\"0.9\" />\n      <stop offset=\"100%\" stop-color=\"#ffffff\" stop-opacity=\"1\" />\n    </linearGradient>\n\n    <!-- Edge Specular Highlight: Top Right Edge -->\n    <linearGradient id=\"topRightSpec\" x1=\"512\" y1=\"172\" x2=\"806\" y2=\"342\" gradientUnits=\"userSpaceOnUse\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\" stop-opacity=\"1\" />\n      <stop offset=\"35%\" stop-color=\"#79c0ff\" stop-opacity=\"0.85\" />\n      <stop offset=\"100%\" stop-color=\"#1f6feb\" stop-opacity=\"0.3\" />\n    </linearGradient>\n\n    <!-- Top Face Glass Fill -->\n    <linearGradient id=\"topFaceGrad\" x1=\"218\" y1=\"172\" x2=\"806\" y2=\"512\" gradientUnits=\"userSpaceOnUse\">\n      <stop offset=\"0%\" stop-color=\"#1f6feb\" stop-opacity=\"0.25\" />\n      <stop offset=\"50%\" stop-color=\"#0e2340\" stop-opacity=\"0.45\" />\n      <stop offset=\"100%\" stop-color=\"#091424\" stop-opacity=\"0.7\" />\n    </linearGradient>\n\n    <!-- Left Face Glass Fill -->\n    <linearGradient id=\"leftFaceGrad\" x1=\"218\" y1=\"342\" x2=\"512\" y2=\"852\" gradientUnits=\"userSpaceOnUse\">\n      <stop offset=\"0%\" stop-color=\"#0f294a\" stop-opacity=\"0.55\" />\n      <stop offset=\"60%\" stop-color=\"#0a192f\" stop-opacity=\"0.75\" />\n      <stop offset=\"100%\" stop-color=\"#050d18\" stop-opacity=\"0.9\" />\n    </linearGradient>\n\n    <!-- Right Face Glass Fill -->\n    <linearGradient id=\"rightFaceGrad\" x1=\"806\" y1=\"342\" x2=\"512\" y2=\"852\" gradientUnits=\"userSpaceOnUse\">\n      <stop offset=\"0%\" stop-color=\"#0a1a30\" stop-opacity=\"0.7\" />\n      <stop offset=\"60%\" stop-color=\"#06101e\" stop-opacity=\"0.85\" />\n      <stop offset=\"100%\" stop-color=\"#02060b\" stop-opacity=\"0.95\" />\n    </linearGradient>\n\n    <!-- Inner Core Diamond Gradient -->\n    <radialGradient id=\"octaCoreGlow\" cx=\"512\" cy=\"512\" r=\"125\" gradientUnits=\"userSpaceOnUse\">\n      <stop offset=\"0%\" stop-color=\"#ffffff\" stop-opacity=\"0.95\" />\n      <stop offset=\"25%\" stop-color=\"#00f0ff\" stop-opacity=\"0.8\" />\n      <stop offset=\"60%\" stop-color=\"#1f6feb\" stop-opacity=\"0.4\" />\n      <stop offset=\"100%\" stop-color=\"#0d1117\" stop-opacity=\"0\" />\n    </radialGradient>\n  </defs>\n\n  <!-- macOS Standard Squircle Background (864x864 with rx=195) -->\n  <rect x=\"80\" y=\"80\" width=\"864\" height=\"864\" rx=\"195\" fill=\"url(#bgGrad)\" filter=\"url(#squircleShadow)\" stroke=\"url(#rimGrad)\" stroke-width=\"2.5\" />\n\n  <!-- Background Orbit Gizmo Rings (Loader Animation Style) -->\n  <circle cx=\"512\" cy=\"512\" r=\"380\" stroke=\"#1f6feb\" stroke-width=\"2\" stroke-dasharray=\"8 12\" stroke-opacity=\"0.32\" />\n  <circle cx=\"512\" cy=\"512\" r=\"414\" stroke=\"#00f0ff\" stroke-width=\"1.6\" stroke-opacity=\"0.22\" />\n  <path d=\"M 190 350 A 380 380 0 0 1 512 132\" fill=\"none\" stroke=\"#00f0ff\" stroke-width=\"3\" stroke-linecap=\"round\" stroke-opacity=\"0.65\" />\n  <path d=\"M 834 674 A 414 414 0 0 1 512 926\" fill=\"none\" stroke=\"#58a6ff\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-opacity=\"0.55\" />\n\n  <!-- Ambient Volumetric Center Glow -->\n  <circle cx=\"512\" cy=\"512\" r=\"360\" fill=\"url(#ambientGlow)\" />\n\n  <!-- ======================================================== -->\n  <!-- 3D CUBE TRANSLUCENT FACETS                                -->\n  <!-- ======================================================== -->\n  <polygon points=\"512,172 806,342 512,512 218,342\" fill=\"url(#topFaceGrad)\" />\n  <polygon points=\"218,342 512,512 512,852 218,682\" fill=\"url(#leftFaceGrad)\" />\n  <polygon points=\"512,512 806,342 806,682 512,852\" fill=\"url(#rightFaceGrad)\" />\n\n  <!-- ======================================================== -->\n  <!-- INNER 3D OCTAHEDRON / DIAMOND CORE (Loader Style)         -->\n  <!-- ======================================================== -->\n  <circle cx=\"512\" cy=\"512\" r=\"120\" fill=\"url(#octaCoreGlow)\" />\n  <!-- Octahedron Facets -->\n  <polygon points=\"512,415 594,472 512,578 430,472\" fill=\"#00f0ff\" fill-opacity=\"0.32\" stroke=\"#67e8f9\" stroke-width=\"4\" stroke-linejoin=\"round\" />\n  <polygon points=\"512,415 594,472 512,512\" fill=\"#79c0ff\" fill-opacity=\"0.45\" />\n  <polygon points=\"430,472 512,415 512,512\" fill=\"#38bdf8\" fill-opacity=\"0.35\" />\n  <polygon points=\"512,578 594,472 512,512\" fill=\"#1f6feb\" fill-opacity=\"0.5\" />\n  <polygon points=\"512,578 430,472 512,512\" fill=\"#0f2744\" fill-opacity=\"0.6\" />\n\n  <!-- ======================================================== -->\n  <!-- 3D WIREFRAME MESH GRID IN LIGHT BLUE (#58a6ff / #79c0ff)  -->\n  <!-- ======================================================== -->\n  <g stroke=\"#79c0ff\" stroke-width=\"12\" stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-opacity=\"0.88\">\n    <!-- Top Face Grid -->\n    <line x1=\"316\" y1=\"399\" x2=\"610\" y2=\"229\" />\n    <line x1=\"414\" y1=\"455\" x2=\"708\" y2=\"285\" />\n    <line x1=\"316\" y1=\"285\" x2=\"610\" y2=\"455\" />\n    <line x1=\"414\" y1=\"229\" x2=\"708\" y2=\"399\" />\n    <!-- Diagonal Triangulation of Top Face -->\n    <line x1=\"218\" y1=\"342\" x2=\"806\" y2=\"342\" stroke-width=\"9\" stroke-opacity=\"0.55\" />\n\n    <!-- Left Face Grid -->\n    <line x1=\"316\" y1=\"399\" x2=\"316\" y2=\"739\" />\n    <line x1=\"414\" y1=\"455\" x2=\"414\" y2=\"795\" />\n    <line x1=\"218\" y1=\"455\" x2=\"512\" y2=\"625\" />\n    <line x1=\"218\" y1=\"569\" x2=\"512\" y2=\"739\" />\n    <!-- Diagonal Triangulation of Left Face -->\n    <line x1=\"218\" y1=\"342\" x2=\"512\" y2=\"852\" stroke-width=\"9\" stroke-opacity=\"0.5\" />\n\n    <!-- Right Face Grid -->\n    <line x1=\"610\" y1=\"455\" x2=\"610\" y2=\"795\" />\n    <line x1=\"708\" y1=\"399\" x2=\"708\" y2=\"739\" />\n    <line x1=\"512\" y1=\"625\" x2=\"806\" y2=\"455\" />\n    <line x1=\"512\" y1=\"739\" x2=\"806\" y2=\"569\" />\n    <!-- Diagonal Triangulation of Right Face -->\n    <line x1=\"806\" y1=\"342\" x2=\"512\" y2=\"852\" stroke-width=\"9\" stroke-opacity=\"0.5\" />\n  </g>\n\n  <!-- Dashed Sub-Wireframe Accents (Matching .me-mesh-face span) -->\n  <g stroke=\"#38bdf8\" stroke-width=\"3.5\" stroke-dasharray=\"7 7\" stroke-opacity=\"0.5\">\n    <line x1=\"218\" y1=\"342\" x2=\"806\" y2=\"682\" />\n    <line x1=\"806\" y1=\"342\" x2=\"218\" y2=\"682\" />\n  </g>\n\n  <!-- ======================================================== -->\n  <!-- MAIN BOLD CUBE WIREFRAME EDGES (Vibrant Electric Blue)    -->\n  <!-- ======================================================== -->\n  <!-- Subtle Neon Glow Underlayer -->\n  <g stroke=\"#1f6feb\" stroke-width=\"42\" stroke-linecap=\"round\" stroke-linejoin=\"round\" opacity=\"0.45\" filter=\"url(#neonGlow)\">\n    <path d=\"M 512 172 L 806 342 L 806 682 L 512 852 L 218 682 L 218 342 Z\" fill=\"none\" />\n    <path d=\"M 512 512 L 512 172 M 512 512 L 218 682 M 512 512 L 806 682\" fill=\"none\" />\n  </g>\n\n  <!-- Primary Solid Cube Wireframe (#2563eb / #1f6feb) -->\n  <g stroke=\"#2563eb\" stroke-width=\"32\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n    <path d=\"M 512 172 L 806 342 L 806 682 L 512 852 L 218 682 L 218 342 Z\" fill=\"none\" />\n    <path d=\"M 512 512 L 512 172 M 512 512 L 218 682 M 512 512 L 806 682\" fill=\"none\" />\n  </g>\n\n  <!-- ======================================================== -->\n  <!-- SPECULAR EDGE RIM HIGHLIGHTS (Crest Glow)                 -->\n  <!-- ======================================================== -->\n  <!-- Center Vertical Crest Ridge -->\n  <line x1=\"512\" y1=\"172\" x2=\"512\" y2=\"512\" stroke=\"url(#centerRidgeSpec)\" stroke-width=\"14\" stroke-linecap=\"round\" />\n  <!-- Top Left Crest Ridge -->\n  <line x1=\"218\" y1=\"342\" x2=\"512\" y2=\"172\" stroke=\"url(#topLeftSpec)\" stroke-width=\"14\" stroke-linecap=\"round\" />\n  <!-- Top Right Crest Ridge -->\n  <line x1=\"512\" y1=\"172\" x2=\"806\" y2=\"342\" stroke=\"url(#topRightSpec)\" stroke-width=\"14\" stroke-linecap=\"round\" />\n\n  <!-- Lower Edge Crest Highlights -->\n  <line x1=\"218\" y1=\"682\" x2=\"512\" y2=\"512\" stroke=\"#58a6ff\" stroke-width=\"10\" stroke-linecap=\"round\" stroke-opacity=\"0.4\" />\n  <line x1=\"806\" y1=\"682\" x2=\"512\" y2=\"512\" stroke=\"#388bfd\" stroke-width=\"10\" stroke-linecap=\"round\" stroke-opacity=\"0.35\" />\n\n  <!-- ======================================================== -->\n  <!-- RADIANT 3D VERTEX CORNER NODES (Loader Style)            -->\n  <!-- ======================================================== -->\n  <!-- Top Apex Vertex Node -->\n  <circle cx=\"512\" cy=\"172\" r=\"20\" fill=\"#00f0ff\" opacity=\"0.35\" filter=\"url(#neonGlow)\" />\n  <circle cx=\"512\" cy=\"172\" r=\"13\" fill=\"#ffffff\" stroke=\"#00f0ff\" stroke-width=\"4\" />\n\n  <!-- Center Hub Vertex Node -->\n  <circle cx=\"512\" cy=\"512\" r=\"24\" fill=\"#00f0ff\" opacity=\"0.45\" filter=\"url(#neonGlow)\" />\n  <circle cx=\"512\" cy=\"512\" r=\"15\" fill=\"#ffffff\" stroke=\"#00f0ff\" stroke-width=\"4.5\" />\n\n  <!-- Upper Left Vertex Node -->\n  <circle cx=\"218\" cy=\"342\" r=\"16\" fill=\"#38bdf8\" opacity=\"0.35\" filter=\"url(#neonGlow)\" />\n  <circle cx=\"218\" cy=\"342\" r=\"11\" fill=\"#ffffff\" stroke=\"#38bdf8\" stroke-width=\"3.5\" />\n\n  <!-- Upper Right Vertex Node -->\n  <circle cx=\"806\" cy=\"342\" r=\"16\" fill=\"#38bdf8\" opacity=\"0.35\" filter=\"url(#neonGlow)\" />\n  <circle cx=\"806\" cy=\"342\" r=\"11\" fill=\"#ffffff\" stroke=\"#38bdf8\" stroke-width=\"3.5\" />\n\n  <!-- Lower Left Vertex Node -->\n  <circle cx=\"218\" cy=\"682\" r=\"15\" fill=\"#1f6feb\" opacity=\"0.3\" filter=\"url(#neonGlow)\" />\n  <circle cx=\"218\" cy=\"682\" r=\"10\" fill=\"#e0f2fe\" stroke=\"#1f6feb\" stroke-width=\"3\" />\n\n  <!-- Lower Right Vertex Node -->\n  <circle cx=\"806\" cy=\"682\" r=\"15\" fill=\"#1f6feb\" opacity=\"0.3\" filter=\"url(#neonGlow)\" />\n  <circle cx=\"806\" cy=\"682\" r=\"10\" fill=\"#e0f2fe\" stroke=\"#1f6feb\" stroke-width=\"3\" />\n\n  <!-- Bottom Apex Vertex Node -->\n  <circle cx=\"512\" cy=\"852\" r=\"16\" fill=\"#00d2ff\" opacity=\"0.35\" filter=\"url(#neonGlow)\" />\n  <circle cx=\"512\" cy=\"852\" r=\"11\" fill=\"#ffffff\" stroke=\"#00d2ff\" stroke-width=\"3.5\" />\n\n  <!-- Subtle Interior Grid Intersection Micro-Nodes -->\n  <g fill=\"#79c0ff\">\n    <circle cx=\"414\" cy=\"455\" r=\"4\" />\n    <circle cx=\"610\" cy=\"455\" r=\"4\" />\n    <circle cx=\"316\" cy=\"399\" r=\"4\" />\n    <circle cx=\"708\" cy=\"399\" r=\"4\" />\n    <circle cx=\"414\" cy=\"229\" r=\"3.5\" />\n    <circle cx=\"610\" cy=\"229\" r=\"3.5\" />\n    <circle cx=\"316\" cy=\"739\" r=\"3.5\" />\n    <circle cx=\"414\" cy=\"795\" r=\"3.5\" />\n    <circle cx=\"610\" cy=\"795\" r=\"3.5\" />\n    <circle cx=\"708\" cy=\"739\" r=\"3.5\" />\n  </g>\n</svg>\n        </div>\n\n        <div class=\"toolbar-divider\"></div>\n\n        <!-- File Operations Menu -->\n        <div class=\"dropdown-wrapper\" id=\"dropdownFile\">\n          <button class=\"tool-btn dropdown-toggle\" id=\"btnDropdownFile\" title=\"File Operations\">\n            <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"folder\"></i></span>\n            <span class=\"btn-label\">File</span>\n            <span class=\"dropdown-arrow\"><i class=\"app-icon arrow-icon\" data-lucide=\"chevron-down\"></i></span>\n          </button>\n          <div class=\"dropdown-menu\" id=\"menuFile\">\n            <button class=\"dropdown-item\" id=\"btnOpenModel\" title=\"Open 3D Model from disk (replaces current scene)\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"folder-open\"></i></span>\n              <span class=\"btn-label\">Open...</span>\n            </button>\n            <button\n              class=\"dropdown-item\"\n              id=\"btnImportModel\"\n              title=\"Import / Append 3D Model from disk into current scene (.glb, .gltf, .obj, .stl)\"\n            >\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"folder-input\"></i></span>\n              <span class=\"btn-label\">Import...</span>\n            </button>\n            <button class=\"dropdown-item\" id=\"btnExportMenu\" title=\"Export 3D Model\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"download\"></i></span>\n              <span class=\"btn-label\">Export...</span>\n            </button>\n            <div class=\"dropdown-divider\" id=\"menuFilePluginsDivider\" style=\"display: none\"></div>\n            <div id=\"menuFilePlugins\"></div>\n          </div>\n        </div>\n\n        <!-- Actions Menu -->\n        <div class=\"dropdown-wrapper\" id=\"dropdownActions\">\n          <button class=\"tool-btn dropdown-toggle\" id=\"btnDropdownActions\" title=\"Actions Menu\">\n            <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"sparkles\"></i></span>\n            <span class=\"btn-label\">Actions</span>\n            <span class=\"dropdown-arrow\"><i class=\"app-icon arrow-icon\" data-lucide=\"chevron-down\"></i></span>\n          </button>\n          <div class=\"dropdown-menu\" id=\"menuActions\">\n            <button class=\"dropdown-item\" id=\"btnFocus\" title=\"Center camera on selection (Key: F)\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"crosshair\"></i></span>\n              <span class=\"btn-label\">Center Selection</span>\n              <span class=\"shortcut-tag\">F</span>\n            </button>\n            <button class=\"dropdown-item\" id=\"btnCenterPivot\" title=\"Center pivot to mesh visual center\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"target\"></i></span>\n              <span class=\"btn-label\">Center Pivot</span>\n            </button>\n            <div class=\"dropdown-divider\"></div>\n            <button class=\"dropdown-item\" id=\"btnExtractSubmesh\" title=\"Separate into loose parts or submeshes\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"scissors\"></i></span>\n              <span class=\"btn-label\">Separate Loose Parts</span>\n            </button>\n            <button class=\"dropdown-item\" id=\"btnMergeMeshes\" title=\"Merge selected meshes into a single combined mesh\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"combine\"></i></span>\n              <span class=\"btn-label\">Merge Meshes</span>\n            </button>\n            <div class=\"dropdown-divider\"></div>\n            <button class=\"dropdown-item\" id=\"btnGroup\" title=\"Group selected meshes (Cmd+G / Ctrl+G)\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"folder-plus\"></i></span>\n              <span class=\"btn-label\">Group Meshes</span>\n              <span class=\"shortcut-tag\">⌘G</span>\n            </button>\n            <button class=\"dropdown-item\" id=\"btnUngroup\" title=\"Ungroup selected group (Cmd+Shift+G / Ctrl+Shift+G)\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"folder-minus\"></i></span>\n              <span class=\"btn-label\">Ungroup</span>\n              <span class=\"shortcut-tag\">⇧⌘G</span>\n            </button>\n            <div class=\"dropdown-divider\"></div>\n            <button class=\"dropdown-item btn-danger\" id=\"btnDeleteSelected\" title=\"Delete selected mesh or group (Key: Del)\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"trash-2\"></i></span>\n              <span class=\"btn-label\">Delete Selected</span>\n              <span class=\"shortcut-tag\">Del</span>\n            </button>\n\n          <div class=\"dropdown-divider\"></div>\n            <button class=\"dropdown-item active\" id=\"btnToggleGrid\" title=\"Toggle ground grid\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"grid-3x3\"></i></span>\n              <span class=\"btn-label\">Ground Grid</span>\n            </button>\n            \n            <div class=\"dropdown-divider\" id=\"menuActionsPluginsDivider\" style=\"display: none\"></div>\n            <div id=\"menuActionsPlugins\"></div>\n          </div>\n        </div>\n\n        <!-- Tools Menu  -->\n        <div class=\"dropdown-wrapper\" id=\"dropdownTools\">\n          <button class=\"tool-btn dropdown-toggle\" id=\"btnDropdownTools\" title=\"Tools & Panels Menu\">\n            <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"wrench\"></i></span>\n            <span class=\"btn-label\">Tools</span>\n            <span class=\"dropdown-arrow\"><i class=\"app-icon arrow-icon\" data-lucide=\"chevron-down\"></i></span>\n          </button>\n          <div class=\"dropdown-menu\" id=\"menuTools\">\n            <!-- Dynamically populated from ToolInterface instances in MeshEditorApp.renderToolsMenu() -->\n            <div class=\"dropdown-divider\" id=\"menuToolsPluginsDivider\" style=\"display: none\"></div>\n            <div id=\"menuToolsPlugins\"></div>\n          </div>\n        </div>\n\n        <!-- View Menu -->\n        <div class=\"dropdown-wrapper\" id=\"dropdownView\">\n          <button class=\"tool-btn dropdown-toggle\" id=\"btnDropdownView\" title=\"View Menu\">\n            <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"eye\"></i></span>\n            <span class=\"btn-label\">View</span>\n            <span class=\"dropdown-arrow\"><i class=\"app-icon arrow-icon\" data-lucide=\"chevron-down\"></i></span>\n          </button>\n          <div class=\"dropdown-menu\" id=\"menuView\">\n            <div class=\"dropdown-header-label\">Layout Mode</div>\n            <button class=\"dropdown-item\" id=\"btnLayoutFloating\" title=\"Floating layout: freely movable windows\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"app-window\"></i></span>\n              <span class=\"btn-label\">Float</span>\n            </button>\n            <button class=\"dropdown-item active\" id=\"btnLayoutStack\" title=\"Stackpanel layout: neatly docked vertical sidebar\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"panel-right\"></i></span>\n              <span class=\"btn-label\">Stack</span>\n            </button>\n            <div class=\"dropdown-divider\" id=\"menuViewPluginsDivider\" style=\"display: none\"></div>\n            <div id=\"menuViewPlugins\"></div>\n          </div>\n        </div>\n\n        <div class=\"toolbar-divider\"></div>\n\n        <!-- History: Undo & Redo -->\n        <div class=\"btn-group history-group\">\n          <button class=\"tool-btn\" id=\"btnUndo\" title=\"Undo (Cmd+Z / Ctrl+Z)\" disabled>\n            <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"undo-2\"></i></span><span class=\"btn-label\">Undo</span>\n          </button>\n          <button class=\"tool-btn\" id=\"btnRedo\" title=\"Redo (Cmd+Shift+Z / Ctrl+Y)\" disabled>\n            <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"redo-2\"></i></span><span class=\"btn-label\">Redo</span>\n          </button>\n        </div>\n\n        <div class=\"toolbar-divider\"></div>\n\n        <!-- Transform Gizmos -->\n        <div class=\"btn-group gizmo-group\">\n          <button class=\"tool-btn active gizmo-btn\" id=\"btnGizmoTranslate\" title=\"Move (Key: M)\">\n            <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"move\"></i></span><span class=\"btn-badge\">M</span>\n          </button>\n          <button class=\"tool-btn gizmo-btn\" id=\"btnGizmoRotate\" title=\"Rotate (Key: E)\">\n            <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"rotate-cw\"></i></span><span class=\"btn-badge\">E</span>\n          </button>\n          <button class=\"tool-btn gizmo-btn\" id=\"btnGizmoScale\" title=\"Scale (Key: R)\">\n            <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"maximize-2\"></i></span><span class=\"btn-badge\">R</span>\n          </button>\n          <button class=\"tool-btn gizmo-btn\" id=\"btnGizmoBounds\" title=\"Bounds (Key: B)\">\n            <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"box-select\"></i></span><span class=\"btn-badge\">B</span>\n          </button>\n        </div>\n\n        <div class=\"btn-group panel-group\">\n          <button class=\"tool-btn panel-btn\" id=\"btnHelp\" title=\"Help & Keyboard Shortcuts\">\n            <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></span>\n          </button>\n        </div>\n      </header>\n\n      <!-- 3D Babylon Canvas -->\n      <canvas id=\"renderCanvas\" tabindex=\"0\"></canvas>\n      <div id=\"selectionMarquee\" class=\"selection-marquee\" style=\"display: none;\"></div>\n\n      <!-- Program Startup 3D Mesh Loading Animation -->\n      <div id=\"appStartupLoader\" class=\"me-loader-overlay me-startup-loader\" role=\"status\" aria-live=\"polite\">\n        <div class=\"me-loader-ambient-glow\"></div>\n        <div class=\"me-loader-content\">\n          <div class=\"me-mesh-stage\" aria-hidden=\"true\">\n            <div class=\"me-orbit-ring me-orbit-ring-1\"></div>\n            <div class=\"me-orbit-ring me-orbit-ring-2\"></div>\n            <div class=\"me-orbit-ring me-orbit-ring-3\"></div>\n            <div class=\"me-3d-scene\">\n              <div class=\"me-3d-mesh-assembly\">\n                <div class=\"me-mesh-face me-face-front\"><span></span></div>\n                <div class=\"me-mesh-face me-face-back\"><span></span></div>\n                <div class=\"me-mesh-face me-face-right\"><span></span></div>\n                <div class=\"me-mesh-face me-face-left\"><span></span></div>\n                <div class=\"me-mesh-face me-face-top\"><span></span></div>\n                <div class=\"me-mesh-face me-face-bottom\"><span></span></div>\n                <div class=\"me-inner-octahedron\">\n                  <div class=\"me-octa-plane me-octa-1\"></div>\n                  <div class=\"me-octa-plane me-octa-2\"></div>\n                  <div class=\"me-octa-plane me-octa-3\"></div>\n                </div>\n              </div>\n            </div>\n            <div class=\"me-ground-holo-grid\">\n              <div class=\"me-laser-scan\"></div>\n            </div>\n          </div>\n          <div class=\"me-loader-info\">\n            <div class=\"me-loader-title\">\n              <span class=\"me-loader-badge\">Loading</span>\n              <span>Mesh Editor</span>\n            </div>\n            <div class=\"me-loader-status\" id=\"startupLoaderText\">Initializing 3D Workspace & Tools...</div>\n            <div class=\"me-loader-progress-row\">\n              <progress aria-label=\"Application startup progress\" class=\"loading-spinner me-startup-spinner\"></progress>\n              <div class=\"me-loader-bar-track\">\n                <div class=\"me-loader-bar-fill\" id=\"startupLoaderBar\"></div>\n              </div>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <!-- Babylon Scene Initialization & Mesh Loading Overlay -->\n      <div id=\"sceneInitLoader\" class=\"me-loader-overlay me-scene-loader\" role=\"status\" aria-live=\"polite\">\n        <div class=\"me-scene-loader-card\">\n          <div class=\"me-icosahedron-stage\" aria-hidden=\"true\">\n            <div class=\"me-gizmo-arc me-gizmo-arc-x\"></div>\n            <div class=\"me-gizmo-arc me-gizmo-arc-y\"></div>\n            <div class=\"me-gizmo-arc me-gizmo-arc-z\"></div>\n            <svg class=\"me-icosahedron-svg\" viewBox=\"0 0 200 200\" fill=\"none\" xmlns=\"http://www.w3.org/2000/svg\">\n              <defs>\n                <linearGradient id=\"meMeshFacetGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n                  <stop offset=\"0%\" stop-color=\"var(--accent-active)\" stop-opacity=\"0.58\" />\n                  <stop offset=\"100%\" stop-color=\"var(--accent-active)\" stop-opacity=\"0.08\" />\n                </linearGradient>\n                <radialGradient id=\"meMeshCoreGlow\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n                  <stop offset=\"0%\" stop-color=\"var(--accent-active)\" stop-opacity=\"0.65\" />\n                  <stop offset=\"100%\" stop-color=\"var(--accent-active)\" stop-opacity=\"0\" />\n                </radialGradient>\n              </defs>\n              <circle cx=\"100\" cy=\"100\" r=\"72\" fill=\"url(#meMeshCoreGlow)\" class=\"me-mesh-core-pulse\" />\n              <g class=\"me-mesh-back-edges\">\n                <polygon points=\"100,24 166,62 100,68\" />\n                <polygon points=\"100,24 34,62 100,68\" />\n                <polygon points=\"34,62 34,138 100,132\" />\n                <polygon points=\"166,62 166,138 100,132\" />\n                <polygon points=\"34,138 100,176 100,132\" />\n                <polygon points=\"166,138 100,176 100,132\" />\n              </g>\n              <g class=\"me-mesh-facets\">\n                <polygon class=\"me-facet me-facet-1\" points=\"100,24 58,78 142,78\" />\n                <polygon class=\"me-facet me-facet-2\" points=\"100,24 34,62 58,78\" />\n                <polygon class=\"me-facet me-facet-3\" points=\"100,24 142,78 166,62\" />\n                <polygon class=\"me-facet me-facet-4\" points=\"34,62 34,138 58,78\" />\n                <polygon class=\"me-facet me-facet-5\" points=\"166,62 142,78 166,138\" />\n                <polygon class=\"me-facet me-facet-6\" points=\"58,78 142,78 100,134\" />\n                <polygon class=\"me-facet me-facet-7\" points=\"34,138 58,78 100,134\" />\n                <polygon class=\"me-facet me-facet-8\" points=\"166,138 100,134 142,78\" />\n                <polygon class=\"me-facet me-facet-9\" points=\"34,138 100,176 100,134\" />\n                <polygon class=\"me-facet me-facet-10\" points=\"166,138 100,134 100,176\" />\n              </g>\n              <g class=\"me-mesh-wireframe\">\n                <polygon points=\"100,24 166,62 166,138 100,176 34,138 34,62\" />\n                <polygon points=\"58,78 142,78 100,134\" />\n                <line x1=\"100\" y1=\"24\" x2=\"58\" y2=\"78\" />\n                <line x1=\"100\" y1=\"24\" x2=\"142\" y2=\"78\" />\n                <line x1=\"34\" y1=\"62\" x2=\"58\" y2=\"78\" />\n                <line x1=\"166\" y1=\"62\" x2=\"142\" y2=\"78\" />\n                <line x1=\"34\" y1=\"138\" x2=\"58\" y2=\"78\" />\n                <line x1=\"166\" y1=\"138\" x2=\"142\" y2=\"78\" />\n                <line x1=\"34\" y1=\"138\" x2=\"100\" y2=\"134\" />\n                <line x1=\"166\" y1=\"138\" x2=\"100\" y2=\"134\" />\n                <line x1=\"100\" y1=\"176\" x2=\"100\" y2=\"134\" />\n              </g>\n              <g class=\"me-mesh-vertices\">\n                <circle cx=\"100\" cy=\"24\" r=\"4\" />\n                <circle cx=\"166\" cy=\"62\" r=\"3.5\" />\n                <circle cx=\"166\" cy=\"138\" r=\"3.5\" />\n                <circle cx=\"100\" cy=\"176\" r=\"4\" />\n                <circle cx=\"34\" cy=\"138\" r=\"3.5\" />\n                <circle cx=\"34\" cy=\"62\" r=\"3.5\" />\n                <circle cx=\"58\" cy=\"78\" r=\"4.5\" />\n                <circle cx=\"142\" cy=\"78\" r=\"4.5\" />\n                <circle cx=\"100\" cy=\"134\" r=\"4.5\" />\n              </g>\n            </svg>\n          </div>\n          <div class=\"me-scene-loader-hud\">\n            <div class=\"me-scene-loader-header\">\n              <progress aria-label=\"Babylon scene initialization\" class=\"loading-spinner me-scene-spinner\"></progress>\n              <span class=\"me-scene-loader-title\" id=\"sceneLoaderTitle\">Initializing Babylon 3D Scene...</span>\n            </div>\n            <div class=\"me-scene-loader-sub\" id=\"sceneLoaderSub\">WEBGL2 ENGINE • SHADER PIPELINE • MESH GEOMETRY</div>\n          </div>\n        </div>\n      </div>\n\n      <!-- Drag & Drop Overlay -->\n      <div id=\"dropOverlay\">\n        <div class=\"drop-icon\"><i class=\"app-icon\" data-lucide=\"upload-cloud\" style=\"width: 48px; height: 48px\"></i></div>\n        <div class=\"drop-text\">Drop 3D Model Here!</div>\n        <div class=\"drop-subtext\">3D models (.glb, .gltf, .obj, .stl) or texture images (.png, .jpg, .webp)</div>\n      </div>\n\n      <!-- Outliner Floating Dialog (Hierarchy Tree of Meshes & Submeshes) -->\n      <div id=\"dialog-outliner\" class=\"floating-dialog\" style=\"top: 64px; left: 16px; width: 320px\">\n        <div class=\"dialog-header\">\n          <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"list-tree\"></i> Scene Objects</span>\n          <div class=\"dialog-actions\">\n            <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n            <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n            <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n          </div>\n        </div>\n        <div class=\"outliner-header-bar\">\n          <input type=\"text\" id=\"outlinerSearch\" class=\"outliner-search-input\" placeholder=\"Filter objects...\" />\n        </div>\n        <div class=\"dialog-body\" style=\"max-height: 440px; padding: 6px\">\n          <div id=\"outlinerTreeContainer\" class=\"outliner-tree\"></div>\n        </div>\n      </div>\n\n\n      <!-- Floating HTML Dialog Containers for dat.GUI (wrapped for Stackpanel mode) -->\n      <div id=\"stackpanelRightSidebar\" class=\"stackpanel-sidebar\">\n        <div id=\"dialog-create-primitive\" class=\"floating-dialog\" style=\"top: 64px; right: 338px; width: 320px; z-index: 55\">\n          <div class=\"dialog-header\">\n            <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"plus-circle\"></i> Create Mesh</span>\n            <div class=\"dialog-actions\">\n              <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n            <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n              <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n            </div>\n          </div>\n          <div class=\"dialog-body\" id=\"gui-create-container\"></div>\n        </div>\n\n        <div id=\"dialog-csg\" class=\"floating-dialog\" style=\"top: 530px; right: 338px; width: 320px\">\n          <div class=\"dialog-header\">\n            <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"shapes\"></i> Constructive Solid Geometry</span>\n            <div class=\"dialog-actions\">\n              <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n            <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n              <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n            </div>\n          </div>\n          <div\n            style=\"\n              padding: 6px 12px;\n              background: rgba(88, 166, 255, 0.12);\n              border-bottom: 1px solid var(--border-color);\n              font-size: 11px;\n              color: var(--accent-color);\n              display: flex;\n              align-items: center;\n              gap: 6px;\n            \"\n          >\n            <i class=\"app-icon\" data-lucide=\"lightbulb\" style=\"color: var(--accent-color)\"></i>\n            <span>Use a tool mesh (created or selected) to carve, merge, or intersect with a target mesh!</span>\n          </div>\n          <div class=\"dialog-body\" id=\"gui-csg-container\"></div>\n        </div>\n\n        <div id=\"dialog-facet\" class=\"floating-dialog\" style=\"top: 320px; right: 16px; width: 340px\">\n  <div class=\"dialog-header\">\n    <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"triangle\"></i> Facet &amp; Vertex Editor</span>\n    <div class=\"dialog-actions\">\n      <button class=\"dialog-btn btn-help\" title=\"Help &amp; Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n      <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n      <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n    </div>\n  </div>\n\n  <div class=\"facet-status-bar\">\n    <div class=\"facet-mode-switcher\">\n      <button id=\"btnFacetModeFace\" class=\"facet-mode-btn active\" title=\"Face Selection Mode (Quads &amp; Triangles)\">\n        <i class=\"app-icon\" data-lucide=\"box-select\"></i> Face\n      </button>\n      <button id=\"btnFacetModeVertex\" class=\"facet-mode-btn\" title=\"Vertex Selection &amp; Translation Mode\">\n        <i class=\"app-icon\" data-lucide=\"circle-dot\"></i> Vertex\n      </button>\n    </div>\n    <button id=\"btnFacetPickToggle\" class=\"facet-toggle-btn active\" title=\"Toggle 3D mesh picking\">\n      <i class=\"app-icon\" data-lucide=\"mouse-pointer\"></i>\n      <span id=\"lblFacetPickState\">Pick: ON</span>\n    </button>\n  </div>\n\n  <div class=\"facet-badge-bar\">\n    <div id=\"facetSelectedBadge\" class=\"facet-badge\">No face picked</div>\n  </div>\n\n  <div id=\"facetVertexCoordsStrip\" class=\"facet-vertex-strip\" style=\"display: none;\">\n    <span class=\"facet-coord-title\"><i class=\"app-icon\" data-lucide=\"move\"></i> Position</span>\n    <div class=\"facet-coord-field\">\n      <label class=\"facet-coord-label\" for=\"facetVertexX\">X</label>\n      <input type=\"number\" id=\"facetVertexX\" class=\"tool-input facet-coord-input\" step=\"0.05\" />\n    </div>\n    <div class=\"facet-coord-field\">\n      <label class=\"facet-coord-label\" for=\"facetVertexY\">Y</label>\n      <input type=\"number\" id=\"facetVertexY\" class=\"tool-input facet-coord-input\" step=\"0.05\" />\n    </div>\n    <div class=\"facet-coord-field\">\n      <label class=\"facet-coord-label\" for=\"facetVertexZ\">Z</label>\n      <input type=\"number\" id=\"facetVertexZ\" class=\"tool-input facet-coord-input\" step=\"0.05\" />\n    </div>\n  </div>\n\n  <div class=\"facet-params-strip\">\n    <div class=\"facet-param-field\">\n      <label class=\"facet-param-label\" for=\"facetInputDistance\">Distance</label>\n      <input type=\"number\" id=\"facetInputDistance\" class=\"tool-input facet-num-input\" value=\"0.5\" step=\"0.1\" min=\"-10\" max=\"20\" />\n    </div>\n    <div class=\"facet-param-field\">\n      <label class=\"facet-param-label\" for=\"facetInputInset\">Inset</label>\n      <input type=\"number\" id=\"facetInputInset\" class=\"tool-input facet-num-input\" value=\"0.25\" step=\"0.05\" min=\"0.05\" max=\"0.95\" />\n    </div>\n    <div class=\"facet-param-field\">\n      <label class=\"facet-param-label\" for=\"facetInputThickness\">Thickness</label>\n      <input type=\"number\" id=\"facetInputThickness\" class=\"tool-input facet-num-input\" value=\"0.2\" step=\"0.05\" min=\"0.01\" max=\"5\" />\n    </div>\n    <div class=\"facet-param-field\">\n      <label class=\"facet-param-label\" for=\"facetInputSegments\">Segments</label>\n      <input type=\"number\" id=\"facetInputSegments\" class=\"tool-input facet-num-input\" value=\"4\" step=\"1\" min=\"2\" max=\"16\" />\n    </div>\n  </div>\n\n  <div class=\"dialog-body facet-tool-body\">\n    <div class=\"mesh-edit-section-header\">\n      <span class=\"mesh-edit-section-chevron\"><i class=\"app-icon\" data-lucide=\"chevron-down\"></i></span>\n      <span class=\"mesh-edit-section-name\">Detail</span>\n    </div>\n    <div class=\"mesh-edit-subtitle\">Mesh Edit</div>\n\n    <div class=\"mesh-edit-list\">\n      <!-- Extrude -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetExtrude\" title=\"Extrude selected face along normal\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #58a6ff\"><i class=\"app-icon\" data-lucide=\"box-select\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Extrude</div>\n          <div class=\"mesh-edit-desc\">Pull new shape from selected faces or edges.</div>\n        </div>\n        <div class=\"mesh-edit-key\">X</div>\n      </div>\n\n      <!-- Inset -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetInset\" title=\"Create inset region on selected face\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #3fb950\"><i class=\"app-icon\" data-lucide=\"maximize-2\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Inset</div>\n          <div class=\"mesh-edit-desc\">Create an inset region on selected faces.</div>\n        </div>\n        <div class=\"mesh-edit-key\">I</div>\n      </div>\n\n      <!-- Arc -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetArc\" title=\"Round selected face into segmented arch\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #bc8cff\"><i class=\"app-icon\" data-lucide=\"circle-dot\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Arc</div>\n          <div class=\"mesh-edit-desc\">Round a selected face into a segmented arch.</div>\n        </div>\n        <div class=\"mesh-edit-key\">Shift+A</div>\n      </div>\n\n      <!-- Knife -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetKnife\" title=\"Place and adjust knife points on selected face\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #f0883e\"><i class=\"app-icon\" data-lucide=\"scissors\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Knife</div>\n          <div class=\"mesh-edit-desc\">Place and adjust knife points on the selected face.</div>\n        </div>\n        <div class=\"mesh-edit-key\">C</div>\n      </div>\n\n      <!-- Loop Cut -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetLoopCut\" title=\"Cut a quad strip through adjacent faces\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #39c5bb\"><i class=\"app-icon\" data-lucide=\"hash\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Loop Cut</div>\n          <div class=\"mesh-edit-desc\">Cut a quad strip through selected edges or adjacent faces.</div>\n        </div>\n        <div class=\"mesh-edit-key\">Shift+E</div>\n      </div>\n\n      <!-- Bevel -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetBevel\" title=\"Chamfer selected objects, edges, or faces\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #d29922\"><i class=\"app-icon\" data-lucide=\"layers\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Bevel</div>\n          <div class=\"mesh-edit-desc\">Chamfer selected objects, edges, or faces.</div>\n        </div>\n        <div class=\"mesh-edit-key\">-</div>\n      </div>\n\n      <!-- Solidify -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetSolidify\" title=\"Add thickness to selected faces or mesh\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #58a6ff\"><i class=\"app-icon\" data-lucide=\"shield\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Solidify</div>\n          <div class=\"mesh-edit-desc\">Add thickness to selected faces.</div>\n        </div>\n        <div class=\"mesh-edit-key\">H</div>\n      </div>\n\n      <!-- Array -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetArray\" title=\"Create offset copies of selected objects or faces\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #79c0ff\"><i class=\"app-icon\" data-lucide=\"grid-3x3\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Array</div>\n          <div class=\"mesh-edit-desc\">Create offset or radial copies of selected objects or faces.</div>\n        </div>\n        <div class=\"mesh-edit-key\"></div>\n      </div>\n\n      <!-- Cut Through -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetCutThrough\" title=\"Turn selected cut face into through-opening\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #e3b341\"><i class=\"app-icon\" data-lucide=\"square-dashed\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Cut Through</div>\n          <div class=\"mesh-edit-desc\">Turn the selected cut face into a through-opening.</div>\n        </div>\n        <div class=\"mesh-edit-key\">T</div>\n      </div>\n\n      <!-- Relax -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetRelax\" title=\"Evenly relax selected vertices while preserving boundary\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #56d364\"><i class=\"app-icon\" data-lucide=\"waves\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Relax</div>\n          <div class=\"mesh-edit-desc\">Evenly relax selected vertices while preserving the outer boundary.</div>\n        </div>\n        <div class=\"mesh-edit-key\">V</div>\n      </div>\n\n      <!-- Subdivide -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetSubdivide\" title=\"Split selected objects or faces into smaller editable faces\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #38bdf8\"><i class=\"app-icon\" data-lucide=\"grid-2x2\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Subdivide</div>\n          <div class=\"mesh-edit-desc\">Split selected objects or faces into smaller editable faces.</div>\n        </div>\n        <div class=\"mesh-edit-key\">K</div>\n      </div>\n\n      <!-- Sub-D -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetSubD\" title=\"Choose smooth subdivision preview levels\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #22d3ee\"><i class=\"app-icon\" data-lucide=\"sparkles\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Sub-D</div>\n          <div class=\"mesh-edit-desc\">Choose smooth subdivision preview levels.</div>\n        </div>\n        <div class=\"mesh-edit-key\">Shift+S</div>\n      </div>\n\n      <!-- Invert Normal -->\n      <div class=\"mesh-edit-item\" id=\"btnFacetFlipNormal\" title=\"Reverse polygon winding order\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #a371f7\"><i class=\"app-icon\" data-lucide=\"refresh-cw\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Invert Normal</div>\n          <div class=\"mesh-edit-desc\">Reverse polygon winding order.</div>\n        </div>\n        <div class=\"mesh-edit-key\">N</div>\n      </div>\n\n      <!-- Delete Face -->\n      <div class=\"mesh-edit-item mesh-edit-item-danger\" id=\"btnFacetDelete\" title=\"Delete selected face geometry\">\n        <div class=\"mesh-edit-icon-wrap\" style=\"color: #f85149\"><i class=\"app-icon\" data-lucide=\"trash-2\"></i></div>\n        <div class=\"mesh-edit-info\">\n          <div class=\"mesh-edit-name\">Delete Face</div>\n          <div class=\"mesh-edit-desc\">Delete selected face geometry.</div>\n        </div>\n        <div class=\"mesh-edit-key\">Del</div>\n      </div>\n    </div>\n\n    <div id=\"gui-facet-container\" style=\"display: none\"></div>\n  </div>\n</div>\n\n        <div id=\"dialog-sculpt\" class=\"floating-dialog\" style=\"top: 140px; right: 16px; width: 340px; display: none\">\n  <div class=\"dialog-header\">\n    <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"sparkles\"></i> Figure Sculpt &amp; Retopo</span>\n    <div class=\"dialog-actions\">\n      <button class=\"dialog-btn btn-help\" title=\"Help &amp; Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n      <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n      <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n    </div>\n  </div>\n  <div class=\"dialog-body sculpt-tool-body\">\n    <!-- Base Mesh Generators -->\n    <div class=\"tool-control-group\">\n      <div class=\"sculpt-section-title\"><i class=\"app-icon\" data-lucide=\"user-check\"></i> Anatomical Base Meshes</div>\n      <div class=\"tool-sublabel\">Spawn proportioned blockouts with joint loops</div>\n      <div class=\"sculpt-grid-2\">\n        <button id=\"btnSpawnHumanoidBase\" class=\"sculpt-btn\" title=\"Loomis 8-Head Humanoid Mannequin (Heroic 1.80m)\">\n          <i class=\"app-icon\" data-lucide=\"user\"></i> Humanoid\n        </button>\n        <button id=\"btnSpawnChibiBase\" class=\"sculpt-btn\" title=\"Stylized / Cartoon 3.5-Head Character (Mario, Dwarf, Toon Mascot)\">\n          <i class=\"app-icon\" data-lucide=\"smile\"></i> Chibi / Toon\n        </button>\n        <button id=\"btnSpawnCreatureBase\" class=\"sculpt-btn\" title=\"Organic Stylized Creature / Chibi Demon (Soft Continuous Contours, Horns, Wings, Pitchfork)\">\n          <i class=\"app-icon\" data-lucide=\"sparkles\"></i> Organic Demon\n        </button>\n        <button id=\"btnSpawnQuadrupedBase\" class=\"sculpt-btn\" title=\"Animal / Creature with Digitigrade Leg Mechanics\">\n          <i class=\"app-icon\" data-lucide=\"paw-print\"></i> Quadruped\n        </button>\n        <button id=\"btnSpawnHeadBust\" class=\"sculpt-btn\" title=\"Head &amp; Facial Plane Bust with Eye Sockets &amp; Jaw\">\n          <i class=\"app-icon\" data-lucide=\"user-check\"></i> Head Bust\n        </button>\n        <button id=\"btnSpawnSculptSphere\" class=\"sculpt-btn\" title=\"Dense Digital Clay Sphere for Freeform Sculpting\">\n          <i class=\"app-icon\" data-lucide=\"circle\"></i> Clay Sphere\n        </button>\n      </div>\n      <div class=\"tool-row\" style=\"margin-top: 6px;\">\n        <span class=\"tool-label\">Mesh Style</span>\n        <select id=\"selectSculptStyle\" class=\"tool-select\" style=\"flex: 1;\">\n          <option value=\"organic\" selected>Organic (Soft Contours)</option>\n          <option value=\"mannequin\">Mannequin (Rigid Joints)</option>\n        </select>\n      </div>\n      <div class=\"tool-row\" style=\"margin-top: 6px;\">\n        <span class=\"tool-label\">Resting Pose</span>\n        <select id=\"selectSculptPose\" class=\"tool-select\" style=\"flex: 1;\">\n          <option value=\"t_pose\" selected>T-Pose (Outstretched)</option>\n          <option value=\"a_pose\">A-Pose (45° Angle)</option>\n        </select>\n      </div>\n    </div>\n\n    <!-- Sculpting Brushes -->\n    <div class=\"tool-control-group\">\n      <div class=\"sculpt-section-title\"><i class=\"app-icon\" data-lucide=\"brush\"></i> Sculpting Brush</div>\n      <div class=\"sculpt-grid-3\">\n        <button class=\"sculpt-btn btn-sculpt-brush active\" data-brush=\"clay\" title=\"Add or carve surface clay along normals\">Clay</button>\n        <button class=\"sculpt-btn btn-sculpt-brush\" data-brush=\"grab\" title=\"Pull geometry smoothly along mouse drag (Primary forms)\">Grab</button>\n        <button class=\"sculpt-btn btn-sculpt-brush\" data-brush=\"smooth\" title=\"Laplacian smoothing to relax wrinkles and bumps\">Smooth</button>\n        <button class=\"sculpt-btn btn-sculpt-brush\" data-brush=\"flatten\" title=\"Project vertices onto contact plane for bone planes\">Flatten</button>\n        <button class=\"sculpt-btn btn-sculpt-brush\" data-brush=\"inflate\" title=\"Expand or contract volume along vertex normals\">Inflate</button>\n        <button class=\"sculpt-btn btn-sculpt-brush\" data-brush=\"pinch\" title=\"Pinch vertices towards center for sharp creases\">Pinch</button>\n      </div>\n    </div>\n\n    <!-- Brush Settings -->\n    <div class=\"tool-control-group\">\n      <div class=\"sculpt-slider-row\">\n        <div class=\"sculpt-slider-header\">\n          <span class=\"sculpt-slider-label\">Brush Radius</span>\n          <span id=\"sculptRadiusValue\" class=\"sculpt-slider-val\">0.35</span>\n        </div>\n        <input type=\"range\" id=\"sliderSculptRadius\" min=\"0.05\" max=\"1.50\" step=\"0.02\" value=\"0.35\" class=\"tool-range\">\n      </div>\n\n      <div class=\"sculpt-slider-row\">\n        <div class=\"sculpt-slider-header\">\n          <span class=\"sculpt-slider-label\">Brush Strength</span>\n          <span id=\"sculptStrengthValue\" class=\"sculpt-slider-val\">0.50</span>\n        </div>\n        <input type=\"range\" id=\"sliderSculptStrength\" min=\"0.05\" max=\"1.00\" step=\"0.05\" value=\"0.50\" class=\"tool-range\">\n      </div>\n\n      <div class=\"sculpt-options-row\">\n        <label class=\"sculpt-checkbox-label\">\n          <input type=\"checkbox\" id=\"chkSculptSymmetry\" checked>\n          <span><strong>X-Symmetry</strong></span>\n        </label>\n        <label class=\"sculpt-checkbox-label\" title=\"Or hold Alt / Ctrl while sculpting\">\n          <input type=\"checkbox\" id=\"chkSculptInvert\">\n          <span>Invert (<kbd>Alt</kbd>)</span>\n        </label>\n      </div>\n    </div>\n\n    <!-- Game-Ready Retopology -->\n    <div class=\"tool-control-group\" style=\"border-top: 1px solid rgba(255, 255, 255, 0.1); padding-top: 10px;\">\n      <div class=\"sculpt-section-title\"><i class=\"app-icon\" data-lucide=\"layers\"></i> Game-Ready Retopology</div>\n      <div class=\"tool-sublabel\">Decimate sculpt into clean, performance-friendly game mesh</div>\n\n      <div class=\"tool-row\" style=\"margin-top: 4px;\">\n        <span class=\"tool-label\">Target Budget</span>\n        <select id=\"selectRetopoPreset\" class=\"tool-select\" style=\"flex: 1;\">\n          <option value=\"4000\">Mobile / WebGL (~4,000)</option>\n          <option value=\"15000\" selected>Standard Game (~15,000)</option>\n          <option value=\"32000\">Hero Asset (~32,000)</option>\n          <option value=\"custom\">Custom Faces</option>\n        </select>\n      </div>\n\n      <div class=\"tool-row\" style=\"margin-top: 4px;\">\n        <span class=\"tool-label\">Target Faces</span>\n        <input type=\"number\" id=\"numRetopoTargetFaces\" class=\"tool-input\" min=\"500\" max=\"100000\" step=\"500\" value=\"15000\" style=\"flex: 1;\">\n      </div>\n\n      <button type=\"button\" id=\"btnExecuteRetopology\" class=\"tool-btn tool-btn-primary btn-block\" style=\"width: 100%; height: 32px; margin-top: 6px;\">\n        <i class=\"app-icon\" data-lucide=\"check-circle-2\"></i> Retopologize to Game Mesh\n      </button>\n    </div>\n\n    <!-- Topology Health & Stats -->\n    <div class=\"sculpt-stats-card\">\n      <div class=\"sculpt-stats-row\">\n        <span style=\"color: #8b949e;\">Active Mesh:</span>\n        <span id=\"sculptMeshName\" style=\"color: #58a6ff; font-weight: 600;\">None</span>\n      </div>\n      <div class=\"sculpt-stats-row\">\n        <span style=\"color: #8b949e;\">Triangles:</span>\n        <span id=\"sculptTriCount\" style=\"color: #f0f6fc; font-weight: 600; font-family: monospace;\">0</span>\n      </div>\n      <div class=\"sculpt-stats-row\">\n        <span style=\"color: #8b949e;\">Vertices:</span>\n        <span id=\"sculptVertCount\" style=\"color: #f0f6fc; font-family: monospace;\">0</span>\n      </div>\n      <div class=\"sculpt-stats-row\">\n        <span style=\"color: #8b949e;\">Game Readiness:</span>\n        <span id=\"sculptGameBadge\" class=\"sculpt-badge-pill\" style=\"background: rgba(35, 134, 54, 0.2); color: #3fb950; border: 1px solid rgba(63, 185, 80, 0.3);\">\n          Ready\n        </span>\n      </div>\n    </div>\n  </div>\n</div>\n\n        <div id=\"dialog-voxel-painter\" class=\"floating-dialog\" style=\"top: 100px; left: 348px; width: 340px; display: none\">\n          <div class=\"dialog-header\">\n            <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"brush\"></i> Voxel Painter</span>\n            <div class=\"dialog-actions\">\n              <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n            <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n              <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n            </div>\n          </div>\n          <div class=\"dialog-body voxel-painter-body\">\n            <!-- Mode Switcher -->\n            <div class=\"voxel-mode-group\">\n              <button class=\"voxel-mode-btn active\" id=\"btnVoxelModePaint\" title=\"Paint block on surface\">\n                <i class=\"app-icon\" data-lucide=\"paintbrush\"></i> Paint\n              </button>\n              <button class=\"voxel-mode-btn\" id=\"btnVoxelModeErase\" title=\"Erase block\">\n                <i class=\"app-icon\" data-lucide=\"eraser\"></i> Erase\n              </button>\n              <button class=\"voxel-mode-btn\" id=\"btnVoxelModePick\" title=\"Eyedropper: pick block material\">\n                <i class=\"app-icon\" data-lucide=\"pipette\"></i> Pick\n              </button>\n            </div>\n\n            <!-- Active Material Preview Card -->\n            <div class=\"voxel-active-preview-card\" id=\"voxelActivePreviewCard\">\n              <div class=\"voxel-active-thumb\" id=\"voxelActiveThumb\"></div>\n              <div class=\"voxel-active-meta\">\n                <span class=\"voxel-active-title\" id=\"voxelActiveTitle\">Stone</span>\n                <span class=\"voxel-active-type\" id=\"voxelActiveType\">Atlas Tile</span>\n              </div>\n              <div class=\"voxel-active-actions\">\n                <button class=\"tool-btn-xs\" id=\"btnVoxelAddTexture\" title=\"Add individual texture image from disk\"><i class=\"app-icon\" data-lucide=\"image\"></i> Add Image</button>\n              </div>\n            </div>\n            <input type=\"file\" id=\"voxelTextureFileInput\" accept=\".png,.jpg,.jpeg,.webp,image/*\" style=\"display: none\" />\n\n            <!-- Visual Texture Picker (Scene Textures & Atlases) -->\n            <div class=\"voxel-section\">\n              <div class=\"voxel-section-header\">\n                <span><i class=\"app-icon\" data-lucide=\"image\"></i> Visual Texture Picker</span>\n                <div class=\"voxel-section-actions\">\n                  <button class=\"tool-btn-xs\" id=\"btnVoxelLoadAtlas\" title=\"Load Texture Atlas (Image + JSON/TPS/XML)\"><i class=\"app-icon\" data-lucide=\"upload\"></i> Atlas</button>\n                </div>\n              </div>\n              <div class=\"voxel-texture-gallery\" id=\"voxelTextureGallery\">\n                <!-- Dynamically populated visual texture cards -->\n              </div>\n              <select id=\"voxelAtlasSelect\" class=\"form-select tool-select\" style=\"margin-top: 2px\">\n                <option value=\"\">Default Terrain Atlas (16 Tiles)</option>\n              </select>\n            </div>\n\n            <!-- Palette Swatches Grid -->\n            <div class=\"voxel-section\">\n              <div class=\"voxel-section-header\">\n                <span><i class=\"app-icon\" data-lucide=\"palette\"></i> Palette Swatches</span>\n                <span id=\"voxelSelectedMaterialName\" class=\"voxel-selected-label\">Stone</span>\n              </div>\n              <div class=\"voxel-palette-grid\" id=\"voxelPaletteGrid\">\n                <!-- Dynamically populated swatches -->\n              </div>\n            </div>\n\n            <!-- Parameters -->\n            <div class=\"voxel-controls-row\">\n              <label for=\"voxelSizeInput\">Size:</label>\n              <input type=\"number\" id=\"voxelSizeInput\" class=\"form-input-sm\" value=\"1.0\" min=\"0.1\" max=\"5.0\" step=\"0.25\" />\n              <label for=\"voxelIntervalInput\">Speed:</label>\n              <input type=\"range\" id=\"voxelIntervalInput\" min=\"50\" max=\"400\" step=\"25\" value=\"150\" title=\"Continuous paint interval (ms)\" />\n            </div>\n\n            <!-- Action Buttons -->\n            <div class=\"voxel-actions-row\">\n              <button class=\"btn btn-primary btn-sm\" id=\"btnVoxelBake\" title=\"Bake painted voxels into an editable 3D mesh in the scene\">\n                <i class=\"app-icon\" data-lucide=\"box\"></i> Bake to 3D Mesh\n              </button>\n              <button class=\"btn btn-secondary btn-sm\" id=\"btnVoxelClear\" title=\"Clear all voxel blocks\">\n                <i class=\"app-icon\" data-lucide=\"trash-2\"></i> Clear\n              </button>\n            </div>\n\n            <div class=\"voxel-io-row\">\n              <button class=\"btn btn-outline btn-xs\" id=\"btnVoxelImportJson\" title=\"Import RLE Voxel Data JSON\">\n                <i class=\"app-icon\" data-lucide=\"upload\"></i> Import JSON\n              </button>\n              <button class=\"btn btn-outline btn-xs\" id=\"btnVoxelExportJson\" title=\"Export RLE Voxel Data JSON\">\n                <i class=\"app-icon\" data-lucide=\"download\"></i> Export JSON\n              </button>\n              <span class=\"voxel-blocks-badge\" id=\"voxelBlocksCount\">0 Blocks</span>\n            </div>\n          </div>\n        </div>\n\n        <div id=\"dialog-path-extrusion\" class=\"floating-dialog\" style=\"top: 100px; left: 700px; width: 340px; display: none\">\n          <div class=\"dialog-header\">\n            <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"route\"></i> Path Extrusion</span>\n            <div class=\"dialog-actions\">\n              <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n            <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n              <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n            </div>\n          </div>\n          <div class=\"dialog-body path-extrusion-body\">\n            <!-- Active Path Extrusion Selector -->\n            <div class=\"path-extrusion-control-group\">\n              <label class=\"path-extrusion-label\" for=\"pathExtrusionSelect\">Active Path Extrusion</label>\n              <div class=\"path-extrusion-row\">\n                <select id=\"pathExtrusionSelect\" class=\"path-extrusion-select\"></select>\n                <button type=\"button\" class=\"btn btn-secondary btn-action-sm\" id=\"btnPathExtrusionNew\" title=\"Create new path extrusion\"><i class=\"app-icon\" data-lucide=\"plus\"></i></button>\n                <button type=\"button\" class=\"btn btn-secondary btn-action-sm btn-danger\" id=\"btnPathExtrusionDelete\" title=\"Delete path extrusion\"><i class=\"app-icon\" data-lucide=\"trash-2\"></i></button>\n              </div>\n            </div>\n\n            <!-- Open Path Extrusion Studio Button -->\n            <button type=\"button\" class=\"btn btn-primary btn-block mb-3\" id=\"btnOpenPathExtrusionStudio\" title=\"Open Interactive 2D Cross-Section Canvas & Presets Studio\" style=\"display:flex;align-items:center;justify-content:center;gap:6px;width:100%;padding:8px 12px;margin-bottom:12px;font-weight:600;\">\n              <i class=\"app-icon\" data-lucide=\"palette\"></i> Open Path Extrusion Studio\n            </button>\n\n            <!-- Help / Status info -->\n            <div class=\"path-extrusion-help-box\">\n              <div class=\"path-extrusion-help-title\"><i class=\"app-icon\" data-lucide=\"info\"></i> 3D Spline Sculpting</div>\n              <div class=\"path-extrusion-help-text\">\n                • <strong>Shift + Click</strong> on ground/mesh to place or append points.<br />\n                • Click any point sphere to attach 3D Gizmo and drag in space.\n              </div>\n            </div>\n\n            <!-- Action buttons -->\n            <div class=\"path-extrusion-actions\">\n              <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"btnPathExtrusionRemovePoint\" title=\"Delete selected waypoint\">\n                <i class=\"app-icon\" data-lucide=\"minus\"></i> Remove Point\n              </button>\n              <button type=\"button\" class=\"btn btn-secondary btn-sm\" id=\"btnPathExtrusionClearPoints\" title=\"Clear all waypoints for this path extrusion\">\n                <i class=\"app-icon\" data-lucide=\"rotate-cw\"></i> Clear Points\n              </button>\n            </div>\n\n            <button type=\"button\" class=\"btn-path-extrusion-bake\" id=\"btnPathExtrusionBakeMesh\">\n              <i class=\"app-icon\" data-lucide=\"check\"></i> Bake to Scene Mesh\n            </button>\n          </div>\n        </div>\n\n        <div id=\"dialog-ai-agent\" class=\"floating-dialog\" style=\"top: 64px; left: 660px; width: 380px; z-index: 58\">\n          <div class=\"dialog-header\">\n            <span class=\"dialog-title\" id=\"aiDialogTitle\"><i class=\"app-icon\" data-lucide=\"bot\" id=\"aiDialogTitleIcon\"></i> <span id=\"aiDialogTitleText\">AI Mesh Agent</span></span>\n            <div class=\"dialog-actions\">\n              <button class=\"dialog-btn\" id=\"btnAISettingsToggle\" title=\"Configure OpenAI-Compatible Endpoint & Skills\">\n                <i class=\"app-icon\" data-lucide=\"settings\"></i>\n              </button>\n              <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n            <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n              <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n            </div>\n          </div>\n\n          <!-- Endpoint & Skills Configuration Drawer -->\n          <div id=\"aiSettingsPanel\" class=\"ai-settings-panel\" style=\"display: none\">\n            <div class=\"ai-settings-title-row\">\n              <span class=\"ai-settings-title\">OpenAI-Compatible Endpoint</span>\n              <div class=\"ai-preset-chips\" id=\"aiPresetChips\">\n                <button type=\"button\" class=\"ai-chip-btn\" data-preset=\"antigravity\">Antigravity</button>\n                <button type=\"button\" class=\"ai-chip-btn\" data-preset=\"gemini\">Gemini Flash</button>\n                <button type=\"button\" class=\"ai-chip-btn\" data-preset=\"gemini-pro\">Gemini Pro</button>\n                <button type=\"button\" class=\"ai-chip-btn\" data-preset=\"openai\">OpenAI</button>\n                <button type=\"button\" class=\"ai-chip-btn\" data-preset=\"openrouter\">OpenRouter</button>\n                <button type=\"button\" class=\"ai-chip-btn\" data-preset=\"omlx\">oMLX</button>\n                <button type=\"button\" class=\"ai-chip-btn\" data-preset=\"ollama\">Ollama</button>\n                <button type=\"button\" class=\"ai-chip-btn\" data-preset=\"lmstudio\">LM Studio</button>\n              </div>\n            </div>\n\n            <div class=\"ai-form-group\">\n              <label for=\"aiEndpointUrlInput\">Base URL</label>\n              <input\n                type=\"text\"\n                id=\"aiEndpointUrlInput\"\n                class=\"ai-input\"\n                placeholder=\"https://api.openai.com/v1\"\n                autocomplete=\"off\"\n              />\n            </div>\n\n            <div class=\"ai-form-group\">\n              <label for=\"aiApiKeyInput\">API Key</label>\n              <div class=\"ai-input-row\">\n                <input\n                  type=\"password\"\n                  id=\"aiApiKeyInput\"\n                  class=\"ai-input\"\n                  placeholder=\"sk-... (optional for local Ollama / LM Studio)\"\n                  autocomplete=\"off\"\n                />\n                <button type=\"button\" class=\"ai-icon-btn\" id=\"btnToggleApiKeyVis\" title=\"Show/Hide API Key\">\n                  <i class=\"app-icon\" data-lucide=\"eye\"></i>\n                </button>\n              </div>\n            </div>\n\n            <div class=\"ai-form-group\">\n              <div class=\"ai-slider-header\" style=\"margin-bottom: 4px;\">\n                <label for=\"aiModelSelect\">Model</label>\n                <button type=\"button\" class=\"ai-link-btn\" id=\"btnToggleCustomModel\" style=\"font-size: 10px; color: var(--accent-hover);\">Custom ID...</button>\n              </div>\n              <div class=\"ai-input-row\">\n                <select id=\"aiModelSelect\" class=\"ai-select tool-select\" style=\"flex: 1; min-width: 0;\">\n                  <option value=\"gemini-3.8-flash-medium\">gemini-3.8-flash-medium</option>\n                  <option value=\"gemini-3.8-flash-high\">gemini-3.8-flash-high</option>\n                  <option value=\"gemini-3.8-flash-low\">gemini-3.8-flash-low</option>\n                  <option value=\"gemini-4-argon-medium\">gemini-4-argon-medium</option>\n                  <option value=\"gemini-4-argon-high\">gemini-4-argon-high</option>\n                  <option value=\"gemini-4-argon-low\">gemini-4-argon-low</option>\n                  <option value=\"claude-sonnet-5-5-medium\">claude-sonnet-5-5-medium</option>\n                  <option value=\"claude-sonnet-5-5-high\">claude-sonnet-5-5-high</option>\n                  <option value=\"claude-sonnet-5-5-low\">claude-sonnet-5-5-low</option>\n                  <option value=\"claude-opus-5-5-medium\">claude-opus-5-5-medium</option>\n                  <option value=\"claude-opus-5-5-high\">claude-opus-5-5-high</option>\n                  <option value=\"claude-opus-5-5-low\">claude-opus-5-5-low</option>\n                  <option value=\"gpt-oss-120b-medium\">gpt-oss-120b-medium</option>\n                  <option value=\"gpt-4o\">gpt-4o</option>\n                  <option value=\"gemini-3-flash-preview\">gemini-3-flash-preview</option>\n                  <option value=\"gemini-3.1-pro-preview\">gemini-3.1-pro-preview</option>\n                  <option value=\"qwen2.5-coder:14b\">qwen2.5-coder:14b</option>\n                </select>\n                <input\n                  type=\"text\"\n                  id=\"aiModelInput\"\n                  class=\"ai-input\"\n                  placeholder=\"gpt-4o\"\n                  autocomplete=\"off\"\n                  style=\"display: none; flex: 1; min-width: 0;\"\n                />\n                <button type=\"button\" class=\"ai-icon-btn\" id=\"btnFetchAIModels\" title=\"Load available models from endpoint (/models)\">\n                  <i class=\"app-icon\" data-lucide=\"refresh-cw\"></i>\n                </button>\n              </div>\n            </div>\n\n            <div class=\"ai-form-group\">\n              <label>Built-in Agent Skills</label>\n              <div id=\"aiSkillsList\" class=\"ai-skills-list\"></div>\n            </div>\n\n            <!-- Mesh Generation Constraints -->\n            <div class=\"ai-settings-title-row\" style=\"margin-top: 6px; padding-top: 6px; border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n              <span class=\"ai-settings-title\">Mesh Generation & Asset Budget</span>\n            </div>\n\n            <div class=\"ai-form-group\">\n              <div class=\"ai-slider-header\">\n                <label for=\"aiMinPolyInput\">Minimum Polygons</label>\n                <span class=\"ai-slider-value\" id=\"aiMinPolyVal\">200</span>\n              </div>\n              <input\n                type=\"range\"\n                id=\"aiMinPolyInput\"\n                class=\"ai-slider\"\n                min=\"50\"\n                max=\"5000\"\n                step=\"50\"\n                value=\"200\"\n              />\n              <div class=\"ai-slider-subtext\">Ensures sufficient geometric definition for game models.</div>\n            </div>\n\n            <div class=\"ai-form-group\">\n              <div class=\"ai-slider-header\">\n                <label for=\"aiMaxPolyInput\">Maximum Polygons</label>\n                <span class=\"ai-slider-value\" id=\"aiMaxPolyVal\">5,000</span>\n              </div>\n              <input\n                type=\"range\"\n                id=\"aiMaxPolyInput\"\n                class=\"ai-slider\"\n                min=\"500\"\n                max=\"1000000\"\n                step=\"500\"\n                value=\"5000\"\n              />\n              <div class=\"ai-preset-chips\" id=\"aiMaxPolyChips\" style=\"margin-top: 5px;\">\n                <button type=\"button\" class=\"ai-chip-btn\" data-poly=\"2500\">2.5k</button>\n                <button type=\"button\" class=\"ai-chip-btn\" data-poly=\"5000\">5k (Default)</button>\n                <button type=\"button\" class=\"ai-chip-btn\" data-poly=\"25000\">25k</button>\n                <button type=\"button\" class=\"ai-chip-btn\" data-poly=\"100000\">100k</button>\n                <button type=\"button\" class=\"ai-chip-btn\" data-poly=\"500000\">500k</button>\n                <button type=\"button\" class=\"ai-chip-btn\" data-poly=\"1000000\">1M</button>\n              </div>\n              <div class=\"ai-slider-subtext\" style=\"margin-top: 4px;\">Target geometric complexity ceiling (500 to 1,000,000 polygons).</div>\n            </div>\n\n            <div class=\"ai-form-group\">\n              <label class=\"ai-checkbox-label\" for=\"aiCreateTexturesCheck\" style=\"cursor: pointer; display: flex; align-items: center; gap: 8px;\">\n                <input type=\"checkbox\" id=\"aiCreateTexturesCheck\" checked />\n                <span><strong>Create Textures</strong></span>\n              </label>\n              <div class=\"ai-slider-subtext\">AI creates PBR textures when checked, otherwise solid PBR colors are used.</div>\n            </div>\n\n            <div class=\"ai-form-group\">\n              <label class=\"ai-checkbox-label\" for=\"aiCreateNormalMapsCheck\" style=\"cursor: pointer; display: flex; align-items: center; gap: 8px;\">\n                <input type=\"checkbox\" id=\"aiCreateNormalMapsCheck\" checked />\n                <span><strong>Create Normal Maps</strong></span>\n              </label>\n              <div class=\"ai-slider-subtext\">AI generates normal/bump maps for surface depth and relief when checked.</div>\n            </div>\n\n            <div class=\"ai-form-group\">\n              <label class=\"ai-checkbox-label\" for=\"aiVisualCritiqueCheck\" style=\"cursor: pointer; display: flex; align-items: center; gap: 8px;\">\n                <input type=\"checkbox\" id=\"aiVisualCritiqueCheck\" />\n                <span><strong>Multi-View Visual Critique</strong></span>\n              </label>\n              <div class=\"ai-slider-subtext\">Renders a 4-view + wireframe inspection sheet after modeling so the AI verifies and self-corrects proportions and polygon density.</div>\n            </div>\n\n            <!-- Neural 3D Generators (Optional BYO 3D Delegation) -->\n            <div class=\"ai-settings-title-row\" style=\"margin-top: 6px; padding-top: 6px; border-top: 1px solid rgba(255, 255, 255, 0.08);\">\n              <span class=\"ai-settings-title\">Neural 3D Generators (Optional BYO 3D)</span>\n            </div>\n            <div class=\"ai-slider-subtext\" style=\"margin-bottom: 6px;\">\n              Enable one or more external 3D generators (via local oMLX / Gradio / FastAPI or cloud API) so the AI Agent can delegate complex organic assets or subtasks.\n            </div>\n\n            <div id=\"aiNeural3DProvidersList\" class=\"ai-skills-list\" style=\"display: flex; flex-direction: column; gap: 8px; margin-bottom: 8px;\">\n              <!-- 1. TRELLIS 2 / TRELLIS -->\n              <div class=\"ai-neural-provider-card\" data-provider-id=\"trellis\" style=\"background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 6px; padding: 8px;\">\n                <div style=\"display: flex; align-items: center; justify-content: space-between; gap: 6px;\">\n                  <label class=\"ai-checkbox-label\" for=\"aiNeuralEnabled_trellis\" style=\"cursor: pointer; display: flex; align-items: center; gap: 8px; margin: 0;\">\n                    <input type=\"checkbox\" id=\"aiNeuralEnabled_trellis\" data-neural-enable=\"trellis\" />\n                    <span><strong>TRELLIS 2 / TRELLIS</strong></span>\n                  </label>\n                  <button type=\"button\" class=\"ai-chip-btn\" id=\"btnTestNeural_trellis\" data-neural-test=\"trellis\" title=\"Test TRELLIS Endpoint Connection\">Test</button>\n                </div>\n                <div class=\"ai-slider-subtext\" style=\"margin-top: 2px;\">Clean SLAT mesh structure &amp; high-fidelity Image/Text-to-3D.</div>\n                <div id=\"aiNeuralConfigBody_trellis\" style=\"display: none; margin-top: 6px; flex-direction: column; gap: 5px;\">\n                  <div class=\"ai-input-row\" style=\"gap: 6px;\">\n                    <select id=\"aiNeuralProtocol_trellis\" class=\"ai-select tool-select\" data-neural-protocol=\"trellis\" style=\"width: 130px;\">\n                      <option value=\"omlx\">oMLX (Local)</option>\n                      <option value=\"local_rest\">Local REST</option>\n                      <option value=\"gradio\">Gradio WebUI</option>\n                      <option value=\"fal\">Fal.ai (Cloud)</option>\n                      <option value=\"replicate\">Replicate</option>\n                    </select>\n                    <input type=\"text\" id=\"aiNeuralModel_trellis\" class=\"ai-input\" placeholder=\"mlx-community/TRELLIS.2-4B\" style=\"flex: 1; min-width: 0;\" />\n                  </div>\n                  <input type=\"text\" id=\"aiNeuralUrl_trellis\" class=\"ai-input\" placeholder=\"http://localhost:8000/v1/3d/generations\" />\n                  <input type=\"password\" id=\"aiNeuralKey_trellis\" class=\"ai-input\" placeholder=\"API Key (optional for local oMLX / Gradio)\" autocomplete=\"off\" />\n                </div>\n              </div>\n\n              <!-- 2. Hunyuan3D -->\n              <div class=\"ai-neural-provider-card\" data-provider-id=\"hunyuan3d\" style=\"background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 6px; padding: 8px;\">\n                <div style=\"display: flex; align-items: center; justify-content: space-between; gap: 6px;\">\n                  <label class=\"ai-checkbox-label\" for=\"aiNeuralEnabled_hunyuan3d\" style=\"cursor: pointer; display: flex; align-items: center; gap: 8px; margin: 0;\">\n                    <input type=\"checkbox\" id=\"aiNeuralEnabled_hunyuan3d\" data-neural-enable=\"hunyuan3d\" />\n                    <span><strong>Hunyuan3D</strong></span>\n                  </label>\n                  <button type=\"button\" class=\"ai-chip-btn\" id=\"btnTestNeural_hunyuan3d\" data-neural-test=\"hunyuan3d\" title=\"Test Hunyuan3D Endpoint Connection\">Test</button>\n                </div>\n                <div class=\"ai-slider-subtext\" style=\"margin-top: 2px;\">Fast Tencent open-source textured 3D object generation.</div>\n                <div id=\"aiNeuralConfigBody_hunyuan3d\" style=\"display: none; margin-top: 6px; flex-direction: column; gap: 5px;\">\n                  <div class=\"ai-input-row\" style=\"gap: 6px;\">\n                    <select id=\"aiNeuralProtocol_hunyuan3d\" class=\"ai-select tool-select\" data-neural-protocol=\"hunyuan3d\" style=\"width: 130px;\">\n                      <option value=\"omlx\">oMLX (Local)</option>\n                      <option value=\"local_rest\">Local REST</option>\n                      <option value=\"gradio\">Gradio WebUI</option>\n                      <option value=\"fal\">Fal.ai (Cloud)</option>\n                      <option value=\"replicate\">Replicate</option>\n                    </select>\n                    <input type=\"text\" id=\"aiNeuralModel_hunyuan3d\" class=\"ai-input\" placeholder=\"mlx-community/Hunyuan3D-2.1\" style=\"flex: 1; min-width: 0;\" />\n                  </div>\n                  <input type=\"text\" id=\"aiNeuralUrl_hunyuan3d\" class=\"ai-input\" placeholder=\"http://localhost:8000/v1/3d/generations\" />\n                  <input type=\"password\" id=\"aiNeuralKey_hunyuan3d\" class=\"ai-input\" placeholder=\"API Key (optional for local oMLX / Gradio)\" autocomplete=\"off\" />\n                </div>\n              </div>\n\n              <!-- 3. Hi3D (V1.0 to V3.0) -->\n              <div class=\"ai-neural-provider-card\" data-provider-id=\"hi3d\" style=\"background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.08); border-radius: 6px; padding: 8px;\">\n                <div style=\"display: flex; align-items: center; justify-content: space-between; gap: 6px;\">\n                  <label class=\"ai-checkbox-label\" for=\"aiNeuralEnabled_hi3d\" style=\"cursor: pointer; display: flex; align-items: center; gap: 8px; margin: 0;\">\n                    <input type=\"checkbox\" id=\"aiNeuralEnabled_hi3d\" data-neural-enable=\"hi3d\" />\n                    <span><strong>Hi3D (V1.0–V3.0)</strong></span>\n                  </label>\n                  <button type=\"button\" class=\"ai-chip-btn\" id=\"btnTestNeural_hi3d\" data-neural-test=\"hi3d\" title=\"Test Hi3D Endpoint Connection\">Test</button>\n                </div>\n                <div class=\"ai-slider-subtext\" style=\"margin-top: 2px;\">High-resolution 2K watertight meshes optimized for 3D printing.</div>\n                <div id=\"aiNeuralConfigBody_hi3d\" style=\"display: none; margin-top: 6px; flex-direction: column; gap: 5px;\">\n                  <div class=\"ai-input-row\" style=\"gap: 6px;\">\n                    <select id=\"aiNeuralProtocol_hi3d\" class=\"ai-select tool-select\" data-neural-protocol=\"hi3d\" style=\"width: 130px;\">\n                      <option value=\"omlx\">oMLX (Local)</option>\n                      <option value=\"local_rest\">Local REST</option>\n                      <option value=\"gradio\">Gradio WebUI</option>\n                      <option value=\"fal\">Fal.ai (Cloud)</option>\n                      <option value=\"replicate\">Replicate</option>\n                    </select>\n                    <input type=\"text\" id=\"aiNeuralModel_hi3d\" class=\"ai-input\" placeholder=\"mlx-community/Hi3D-V3.0\" style=\"flex: 1; min-width: 0;\" />\n                  </div>\n                  <input type=\"text\" id=\"aiNeuralUrl_hi3d\" class=\"ai-input\" placeholder=\"http://localhost:8000/v1/3d/generations\" />\n                  <input type=\"password\" id=\"aiNeuralKey_hi3d\" class=\"ai-input\" placeholder=\"API Key (optional for local oMLX / Gradio)\" autocomplete=\"off\" />\n                </div>\n              </div>\n            </div>\n\n            <div class=\"ai-settings-actions\" style=\"display: flex; gap: 8px;\">\n              <button type=\"button\" class=\"tool-btn\" id=\"btnCancelAISettings\" style=\"flex: 1;\">\n                <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"arrow-left\"></i></span>\n                <span class=\"btn-label\">Back</span>\n              </button>\n              <button type=\"button\" class=\"tool-btn btn-primary\" id=\"btnSaveAISettings\" style=\"flex: 1.5;\">\n                <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"check\"></i></span>\n                <span class=\"btn-label\">Save Settings</span>\n              </button>\n            </div>\n          </div>\n\n          <div class=\"dialog-body ai-agent-body\" id=\"aiAgentBody\">\n            <!-- Status & Mode Bar -->\n            <div class=\"ai-mode-bar\">\n              <select id=\"aiActionModeSelect\" class=\"ai-select tool-select\" title=\"Choose how generated meshes interact with current scene\">\n                <option value=\"create_or_update\">Create / Update in Scene</option>\n                <option value=\"replace_scene\">Replace Scene (Clear First)</option>\n              </select>\n            </div>\n\n            <!-- Dedicated Checkbox Options Row -->\n            <div class=\"ai-checkbox-row\" id=\"aiCheckboxRow\">\n              <label class=\"ai-checkbox-label\" title=\"Generate procedural and seamless textures on created meshes\">\n                <input type=\"checkbox\" id=\"aiCreateTexturesCheckQuick\" checked />\n                <span>Textures</span>\n              </label>\n              <label class=\"ai-checkbox-label\" title=\"Generate normal/bump maps for surface micro-relief and depth\">\n                <input type=\"checkbox\" id=\"aiCreateNormalMapsCheckQuick\" checked />\n                <span>Normal Maps</span>\n              </label>\n              <label class=\"ai-checkbox-label\" title=\"Multi-View Visual Critique: AI inspects a 4-angle + wireframe render of its generation and self-corrects\">\n                <input type=\"checkbox\" id=\"aiVisualCritiqueCheckQuick\" />\n                <span>Visual Check</span>\n              </label>\n              <label class=\"ai-checkbox-label\" title=\"Send a screenshot of the current 3D viewport to the vision model\">\n                <input type=\"checkbox\" id=\"aiIncludeViewportCheck\" />\n                <span>+ 3D View</span>\n              </label>\n            </div>\n\n            <div class=\"ai-endpoint-summary\" id=\"aiEndpointSummaryBar\">\n              <span class=\"ai-endpoint-dot\" id=\"aiEndpointStatusDot\"></span>\n              <span id=\"aiEndpointSummaryText\">Model: gpt-4o</span>\n              <button type=\"button\" class=\"ai-link-btn\" id=\"btnOpenAISettingsInline\">Configure</button>\n            </div>\n\n            <!-- Quick Example Prompts (Compact Select-like Dropdown with Image Support) -->\n            <div class=\"ai-quick-prompts-container\" id=\"aiQuickPrompts\">\n              <div class=\"ai-quick-select-wrapper\" id=\"aiQuickSelectWrapper\">\n                <button\n                  type=\"button\"\n                  class=\"ai-quick-select-btn\"\n                  id=\"btnAIQuickSelect\"\n                  aria-haspopup=\"listbox\"\n                  aria-expanded=\"false\"\n                  title=\"Choose an AI modeling quick prompt example\"\n                >\n                  <span class=\"ai-quick-select-current\" id=\"aiQuickSelectCurrent\">\n                    <span class=\"ai-quick-select-thumb-preview\" id=\"aiQuickSelectThumb\" style=\"display: none\">\n                      <img id=\"aiQuickSelectThumbImg\" src=\"\" alt=\"\" />\n                    </span>\n                    <span class=\"ai-quick-select-icon\" id=\"aiQuickSelectIcon\"><i class=\"app-icon\" data-lucide=\"sparkles\"></i></span>\n                    <span class=\"ai-quick-select-text\" id=\"aiQuickSelectText\">Quick Prompts (Examples)...</span>\n                  </span>\n                  <span class=\"ai-quick-select-chevron\"><i class=\"app-icon\" data-lucide=\"chevron-down\"></i></span>\n                </button>\n\n                <select id=\"aiQuickPromptSelect\" class=\"ai-quick-native-select\" style=\"display: none;\" aria-hidden=\"true\">\n                  <option value=\"\">Quick Prompts (Examples)...</option>\n                </select>\n\n                <div class=\"ai-quick-select-menu\" id=\"aiQuickPromptMenu\" style=\"display: none;\" role=\"listbox\"></div>\n              </div>\n            </div>\n\n            <!-- Chat & Tool Execution Log -->\n            <div id=\"aiChatLog\" class=\"ai-chat-log\"></div>\n\n            <!-- Attached Images Preview Bar -->\n            <div id=\"aiImageAttachmentsBar\" class=\"ai-image-attachments\" style=\"display: none\"></div>\n\n            <!-- Prompt Input & Controls -->\n            <div class=\"ai-input-area\">\n              <textarea\n                id=\"aiPromptInput\"\n                class=\"ai-prompt-textarea\"\n                rows=\"3\"\n                placeholder=\"Enter a prompt (e.g. 'Build a stone archway' or 'Add a roof to selected mesh')... Attach images via button, Drag & Drop or Cmd+V.\"\n              ></textarea>\n              <div class=\"ai-controls-row\">\n                <div class=\"ai-controls-left\">\n                  <button type=\"button\" class=\"tool-btn\" id=\"btnAIRecordSpeech\" title=\"Voice: Record prompt using Speech-to-Text\">\n                    <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"mic\"></i></span>\n                  </button>\n                  <button type=\"button\" class=\"tool-btn\" id=\"btnAIAttachImage\" title=\"Attach Image: Reference image for Image-to-Mesh\">\n                    <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"image\"></i></span>\n                  </button>\n                  <button type=\"button\" class=\"tool-btn\" id=\"btnAICaptureView\" title=\"Capture View: Attach screenshot of current 3D viewport\">\n                    <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"camera\"></i></span>\n                  </button>\n                  <button type=\"button\" class=\"tool-btn\" id=\"btnAIClearChat\" title=\"Clear Chat: Reset AI conversation history\">\n                    <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"trash-2\"></i></span>\n                  </button>\n                </div>\n                <div class=\"ai-controls-right\">\n                  <button type=\"button\" class=\"tool-btn btn-danger\" id=\"btnAIStop\" style=\"display: none\" title=\"Stop: Cancel running AI generation\">\n                    <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"square\"></i></span>\n                  </button>\n                  <button type=\"button\" class=\"tool-btn btn-primary\" id=\"btnAIGenerate\" title=\"Generate: Run AI Mesh Agent (Enter / Cmd+Enter)\">\n                    <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"send\"></i></span>\n                  </button>\n                </div>\n              </div>\n            </div>\n          </div>\n        </div>\n\n        <div id=\"dialog-mesh\" class=\"floating-dialog\" style=\"top: 64px; left: 348px; width: 300px\">\n          <div class=\"dialog-header\">\n            <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"box\"></i> Mesh Properties</span>\n            <div class=\"dialog-actions\">\n              <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n            <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n              <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n            </div>\n          </div>\n          <div class=\"dialog-body\" id=\"gui-mesh-container\"></div>\n        </div>\n\n        <div id=\"dialog-material\" class=\"floating-dialog\" style=\"top: 260px; left: 16px; width: 320px\">\n  <div class=\"dialog-header\">\n    <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"palette\"></i> Material & Texture</span>\n    <div class=\"dialog-actions\">\n      <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n      <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n      <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n    </div>\n  </div>\n  <div class=\"dialog-body\" id=\"gui-material-container\"></div>\n  <div class=\"embedded-textures-section\" id=\"embeddedTexturesSection\">\n    <div class=\"embedded-textures-header\">\n      <span class=\"embedded-textures-title\"><i class=\"app-icon\" data-lucide=\"image\"></i> Embedded Textures (<span id=\"embeddedTexturesCount\">0</span>)</span>\n      <div class=\"embedded-textures-actions\">\n        <button class=\"tool-btn-xs\" id=\"btnEmbedAddTexture\" title=\"Embed texture image file\"><i class=\"app-icon\" data-lucide=\"plus\"></i> Add</button>\n        <button class=\"tool-btn-xs\" id=\"btnEmbedLoadAtlas\" title=\"Load Texture Atlas (Image + JSON/TPS/XML)\"><i class=\"app-icon\" data-lucide=\"grid-3x3\"></i> Atlas</button>\n      </div>\n    </div>\n    <div class=\"embedded-textures-gallery\" id=\"embeddedTexturesGallery\">\n      <div class=\"textures-empty-state\">No custom textures embedded yet.</div>\n    </div>\n\n    <!-- Atlas Sub-Texture / Tile Picker Section -->\n    <div class=\"atlas-tile-picker-section\" id=\"atlasTilePickerSection\" style=\"display: none\">\n      <div class=\"atlas-tile-picker-header\">\n        <span class=\"atlas-tile-picker-title\" id=\"atlasTilePickerTitle\">\n          <i class=\"app-icon\" data-lucide=\"grid-3x3\"></i> Atlas Tiles\n        </span>\n        <button class=\"dialog-btn-xs\" id=\"btnCloseAtlasTilePicker\" title=\"Close Tiles\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n      </div>\n      <div class=\"atlas-tile-picker-grid\" id=\"atlasTilePickerGrid\">\n        <!-- Dynamically populated tiles -->\n      </div>\n      <div class=\"atlas-tile-selected-bar\" id=\"atlasTileSelectedBar\" style=\"display: none\">\n        <div class=\"atlas-tile-selected-preview\" id=\"atlasTileSelectedPreview\"></div>\n        <div class=\"atlas-tile-selected-info\">\n          <div class=\"atlas-tile-selected-name\" id=\"atlasTileSelectedName\">Tile Name</div>\n          <div class=\"atlas-tile-selected-dim\" id=\"atlasTileSelectedDim\">32x32px</div>\n        </div>\n        <div class=\"atlas-tile-selected-actions\">\n          <button class=\"tool-btn-xs tool-btn-primary\" id=\"btnApplyAtlasTileToMaterial\" title=\"Apply this tile to selected mesh material\">\n            <i class=\"app-icon\" data-lucide=\"check\"></i> Apply\n          </button>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n\n        <div id=\"dialog-textures\" class=\"floating-dialog\" style=\"top: 560px; right: 16px; width: 310px\">\n          <div class=\"dialog-header\">\n            <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"zap\"></i> Texture Optimizer</span>\n            <div class=\"dialog-actions\">\n              <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n            <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n              <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n            </div>\n          </div>\n          <div class=\"dialog-body\" id=\"gui-textures-container\"></div>\n        </div>\n\n        <div id=\"dialog-compress-model\" class=\"floating-dialog\" style=\"top: 140px; right: 16px; width: 340px; display: none\">\n  <div class=\"dialog-header\">\n    <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"file-archive\"></i> Compress Model</span>\n    <div class=\"dialog-actions\">\n      <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n      <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n      <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n    </div>\n  </div>\n  <div class=\"dialog-body compress-model-body\">\n\n    <!-- Source Selection: Scene vs External File -->\n    <div class=\"tool-control-group\">\n      <label class=\"tool-label\" for=\"compressModelSourceSelect\">Source</label>\n      <select id=\"compressModelSourceSelect\" class=\"tool-select\">\n        <option value=\"scene\" selected>Active Scene / Selection</option>\n        <option value=\"file\">Import 3D File (.glb, .gltf, .obj, .stl, .ply, .fbx)</option>\n      </select>\n    </div>\n\n    <!-- Drag & Drop Zone for Files -->\n    <div id=\"compressDropZone\" class=\"compress-dropzone\" style=\"display: none\">\n      <input type=\"file\" id=\"compressFileInput\" class=\"hidden-input\" accept=\".glb,.gltf,.obj,.stl,.ply,.fbx\" />\n      <div class=\"compress-dropzone-inner\" id=\"compressDropZoneInner\">\n        <i class=\"app-icon\" data-lucide=\"upload-cloud\"></i>\n        <div class=\"compress-dropzone-text\">Drop 3D file here or <span class=\"compress-browse-link\" id=\"compressBrowseLink\">Browse</span></div>\n        <div class=\"compress-dropzone-sub\">GLB, GLTF, OBJ, STL, PLY, FBX</div>\n      </div>\n      <div id=\"compressLoadedFileInfo\" class=\"compress-file-info\" style=\"display: none\">\n        <i class=\"app-icon\" data-lucide=\"file-check\"></i>\n        <span id=\"compressLoadedFileName\" class=\"compress-file-name\">model.glb</span>\n        <span id=\"compressLoadedFileSize\" class=\"compress-file-size\">4.2 MB</span>\n        <button type=\"button\" id=\"btnCompressClearFile\" class=\"compress-clear-btn\" title=\"Remove file\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n      </div>\n    </div>\n\n    <!-- Compression Presets -->\n    <div class=\"tool-control-group\">\n      <label class=\"tool-label\" for=\"compressPresetSelect\">Compression Level</label>\n      <select id=\"compressPresetSelect\" class=\"tool-select\">\n        <option value=\"lossless\" selected>Lossless (Standard - 100% Polygons Kept)</option>\n        <option value=\"draco_balanced\">Draco Compression (High - GLB / GLTF)</option>\n        <option value=\"draco_ultra\">Draco Compression (Ultra - Smallest Size)</option>\n        <option value=\"decimate_50\">Balanced Decimation (50% Polygon Reduction)</option>\n        <option value=\"custom\">Custom Configuration...</option>\n      </select>\n      <div id=\"compressPresetDesc\" class=\"compress-preset-desc\">\n        Removes duplicate vertices and unused geometry data without altering any polygons.\n      </div>\n    </div>\n\n    <!-- Advanced Settings (Collapsible / Visible when Custom or toggled) -->\n    <div id=\"compressAdvancedSection\" class=\"compress-advanced-box\" style=\"display: none\">\n      <div class=\"compress-checkbox-row\">\n        <label class=\"compress-checkbox-label\">\n          <input type=\"checkbox\" id=\"chkCompressWeld\" checked />\n          <span>Weld duplicate vertices</span>\n        </label>\n      </div>\n      <div class=\"compress-checkbox-row\">\n        <label class=\"compress-checkbox-label\">\n          <input type=\"checkbox\" id=\"chkCompressDegenerate\" checked />\n          <span>Remove degenerate / zero-area faces</span>\n        </label>\n      </div>\n      <div class=\"compress-checkbox-row\">\n        <label class=\"compress-checkbox-label\">\n          <input type=\"checkbox\" id=\"chkCompressUnused\" checked />\n          <span>Purge unreferenced vertex buffers</span>\n        </label>\n      </div>\n      <div class=\"compress-checkbox-row\">\n        <label class=\"compress-checkbox-label\">\n          <input type=\"checkbox\" id=\"chkCompressDraco\" />\n          <span>Draco geometry encoding (GLB / GLTF)</span>\n        </label>\n      </div>\n      <div class=\"compress-slider-row\">\n        <div class=\"tool-row\">\n          <span class=\"tool-label\">Polygon Decimation</span>\n          <span id=\"compressDecimateValue\" class=\"compress-slider-val\">0% (Lossless)</span>\n        </div>\n        <input type=\"range\" id=\"sliderCompressDecimate\" min=\"0\" max=\"80\" step=\"5\" value=\"0\" class=\"tool-range\" />\n      </div>\n      <div class=\"compress-checkbox-row\">\n        <label class=\"compress-checkbox-label\">\n          <input type=\"checkbox\" id=\"chkCompressWebP\" />\n          <span>Convert textures to WebP (80% Quality)</span>\n        </label>\n      </div>\n    </div>\n\n    <!-- Export Format Selector -->\n    <div class=\"tool-control-group\">\n      <label class=\"tool-label\" for=\"compressExportFormatSelect\">Export Format</label>\n      <select id=\"compressExportFormatSelect\" class=\"tool-select\">\n        <option value=\"glb\" selected>GLB (Binary glTF - Recommended)</option>\n        <option value=\"gltf\">glTF (JSON + Bin)</option>\n        <option value=\"obj\">OBJ (Wavefront Mesh)</option>\n        <option value=\"stl\">STL (3D Print Triangle Mesh)</option>\n      </select>\n    </div>\n\n    <!-- Live Comparison Metrics Dashboard -->\n    <div class=\"compress-stats-card\" id=\"compressStatsCard\">\n      <div class=\"compress-stats-header\">\n        <span class=\"compress-stats-title\"><i class=\"app-icon\" data-lucide=\"bar-chart-2\"></i> Optimization Results</span>\n        <span id=\"compressSavingsBadge\" class=\"compress-savings-badge\" style=\"display: none\">-0%</span>\n      </div>\n      <div class=\"compress-metrics-grid\">\n        <div class=\"compress-metric-item\">\n          <div class=\"compress-metric-label\">Size</div>\n          <div id=\"compressMetricSize\" class=\"compress-metric-val\">--</div>\n        </div>\n        <div class=\"compress-metric-item\">\n          <div class=\"compress-metric-label\">Vertices</div>\n          <div id=\"compressMetricVerts\" class=\"compress-metric-val\">--</div>\n        </div>\n        <div class=\"compress-metric-item\">\n          <div class=\"compress-metric-label\">Polygons / Faces</div>\n          <div id=\"compressMetricFaces\" class=\"compress-metric-val\">--</div>\n        </div>\n      </div>\n      <div id=\"compressStatusNotice\" class=\"compress-status-notice\">\n        Ready. Select settings and click Compress.\n      </div>\n    </div>\n\n    <!-- Action Buttons -->\n    <div class=\"compress-actions-row\">\n      <button type=\"button\" id=\"btnCompressDownload\" class=\"tool-btn tool-btn-primary btn-block\">\n        <i class=\"app-icon\" data-lucide=\"download\"></i> Compress &amp; Download\n      </button>\n      <button type=\"button\" id=\"btnCompressApplyScene\" class=\"tool-btn btn-block\" title=\"Apply compression directly into the active 3D scene\">\n        <i class=\"app-icon\" data-lucide=\"check\"></i> Apply to Scene\n      </button>\n    </div>\n  </div>\n</div>\n\n\n        <div id=\"dialog-scene\" class=\"floating-dialog\" style=\"top: 64px; right: 16px; width: 310px\">\n          <div class=\"dialog-header\">\n            <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"sun-medium\"></i> Scene & Environment</span>\n            <div class=\"dialog-actions\">\n              <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n            <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n              <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n            </div>\n          </div>\n          <div class=\"dialog-body\" id=\"gui-scene-container\"></div>\n        </div>\n\n        <div\n          id=\"dialog-anim\"\n          class=\"floating-dialog\"\n          style=\"bottom: 46px; left: 50%; transform: translateX(-50%); width: 440px\"\n        >\n          <div class=\"dialog-header\">\n            <span class=\"dialog-title\"><i class=\"app-icon\" data-lucide=\"film\"></i> Animation Player</span>\n            <div class=\"dialog-actions\">\n              <button class=\"dialog-btn btn-help\" title=\"Help & Tool Guide\" aria-label=\"Help\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></button>\n            <button class=\"dialog-btn btn-min\" title=\"Minimize\"><i class=\"app-icon\" data-lucide=\"minus\"></i></button>\n              <button class=\"dialog-btn btn-close\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n            </div>\n          </div>\n          <div class=\"dialog-body\" id=\"gui-anim-container\"></div>\n        </div>\n\n      </div>\n\n      <!-- Bottom Status Bar -->\n      <footer id=\"bottom-bar\">\n        <div class=\"status-left\">\n          <span class=\"status-badge\" id=\"statusIndicator\"></span>\n          <span class=\"status-message\" id=\"statusText\">Ready. Drag a 3D file here or click \"Open\".</span>\n        </div>\n\n        <div class=\"status-center\">\n          <span><span class=\"shortcut-tag\">Left Click</span> Select / Gizmo</span>\n          <span><span class=\"shortcut-tag\">Right Click</span> Orbit Camera</span>\n          <span><span class=\"shortcut-tag\">W A S D</span> Fly Camera</span>\n          <span><span class=\"shortcut-tag\">Del</span> Delete Selected</span>\n        </div>\n\n        <div class=\"status-right\">\n          <div class=\"stats-item\"><span>Selected:</span> <strong id=\"statsSelection\">None</strong></div>\n          <div class=\"stats-item\"><span>Meshes:</span> <strong id=\"statsMeshes\">0</strong></div>\n          <div class=\"stats-item\"><span>Polygons:</span> <strong id=\"statsPolys\">0</strong></div>\n        </div>\n      </footer>\n\n      <!-- Tool Help Guide Modal Popup -->\n      <div id=\"toolHelpModal\">\n        <div class=\"tool-help-dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"toolHelpTitle\">\n          <div class=\"tool-help-header\">\n            <div class=\"tool-help-title-group\">\n              <span class=\"tool-help-icon\" id=\"toolHelpIcon\"><i class=\"app-icon\" data-lucide=\"help-circle\"></i></span>\n              <div class=\"tool-help-title-col\">\n                <div class=\"tool-help-title-row\">\n                  <h3 class=\"tool-help-title\" id=\"toolHelpTitle\">Tool Guide</h3>\n                  <span class=\"tool-help-badge\" id=\"toolHelpBadge\">3D Tool</span>\n                </div>\n                <div class=\"tool-help-desc\" id=\"toolHelpDesc\">Tool overview and capabilities guide.</div>\n              </div>\n            </div>\n            <button class=\"dialog-btn btn-close\" id=\"btnCloseToolHelp\" title=\"Close Guide\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n          </div>\n          <div class=\"tool-help-body\" id=\"toolHelpBody\"></div>\n          <div class=\"tool-help-footer\">\n            <button class=\"tool-btn btn-primary\" id=\"btnDoneToolHelp\">Got it!</button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Help Modal Dialog -->\n      <div id=\"helpModal\">\n        <div class=\"modal-content\">\n          <div class=\"modal-header\">\n            <h3><i class=\"app-icon\" data-lucide=\"help-circle\"></i> Mesh Editor Guide & Shortcuts</h3>\n            <button class=\"dialog-btn btn-close\" id=\"btnCloseHelp\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n          </div>\n          <div class=\"modal-body\">\n            <div class=\"help-section\">\n              <h4><i class=\"app-icon\" data-lucide=\"mouse\"></i> Mouse Controls & Selection</h4>\n              <table class=\"help-table\">\n                <tr>\n                  <td>Left Click</td>\n                  <td>Select mesh or facet & drag transform gizmos</td>\n                </tr>\n                <tr>\n                  <td>Shift+Click / Cmd+Click</td>\n                  <td>Toggle selection / multi-select individual meshes</td>\n                </tr>\n                <tr>\n                  <td>Click & Drag (Viewport)</td>\n                  <td>Marquee / rectangle box select multiple meshes (Shift/Cmd for additive)</td>\n                </tr>\n                <tr>\n                  <td>Click on Ground / Empty Space</td>\n                  <td>Clear selection (unless Shift or Cmd is held)</td>\n                </tr>\n                <tr>\n                  <td>Right Click (Hold & Drag)</td>\n                  <td>Orbit & rotate camera freely in 3D</td>\n                </tr>\n                \n              </table>\n            </div>\n\n            <div class=\"help-section\">\n              <h4><i class=\"app-icon\" data-lucide=\"keyboard\"></i> Keyboard Shortcuts & Snapping</h4>\n              <table class=\"help-table\">\n                <tr>\n                  <td><span class=\"shortcut-tag\">W, A, S, D</span> / <span class=\"shortcut-tag\">Arrows</span></td>\n                  <td>Fly camera through the 3D scene (no gizmo conflict)</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">M</span></td>\n                  <td>Activate Move (Translate) gizmo</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">E</span></td>\n                  <td>Activate Rotate gizmo</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">R</span></td>\n                  <td>Activate Scale gizmo</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">B</span></td>\n                  <td>Activate Bounds (Bounding Box) gizmo</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">Cmd / Ctrl</span> (Hold while dragging)</td>\n                  <td>Snap movement to Move Grid (default: 0.1) or rotation to angle steps (default: 5°)</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">F</span></td>\n                  <td>Focus camera on selected object(s)</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">Cmd+Z / Ctrl+Z</span></td>\n                  <td>Undo last action</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">Cmd+Shift+Z / Cmd+Y</span></td>\n                  <td>Redo action</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">Cmd+G / Ctrl+G</span></td>\n                  <td>Group selected meshes (Shift+Cmd+G to ungroup)</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">Cmd+C / Ctrl+C</span></td>\n                  <td>Copy selected mesh(es)</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">Cmd+V / Ctrl+V</span></td>\n                  <td>Paste copied mesh(es) at 3D cursor position</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">Cmd+D / Ctrl+D</span></td>\n                  <td>Duplicate selected mesh(es)</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">Cmd+E / Ctrl+E</span></td>\n                  <td>Open Export 3D Model dialog</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">Del / Backspace</span></td>\n                  <td>Delete selected mesh(es) or facet</td>\n                </tr>\n                <tr>\n                  <td><span class=\"shortcut-tag\">Escape</span></td>\n                  <td>Cancel active tool / deselect / close dialogs</td>\n                </tr>\n              </table>\n            </div>\n\n            <div class=\"help-section\">\n              <h4><i class=\"app-icon\" data-lucide=\"layers\"></i> Multi-Selection & Scene Tree</h4>\n              <p style=\"font-size: 13px; color: var(--text-secondary); line-height: 1.5\">\n                • <strong>Unified Multi-Transform:</strong> When multiple meshes are selected, a bounding proxy gizmo moves, rotates, and scales all items together with undo/redo support.<br />\n                • <strong>Outliner Tree Selection:</strong> Click any mesh in the Scene Outliner to select it. Use <span class=\"shortcut-tag\" style=\"font-size:10px\">Cmd/Ctrl+Click</span> to toggle multi-selection or <span class=\"shortcut-tag\" style=\"font-size:10px\">Shift+Click</span> for range selection.<br />\n                • <strong>Gizmo Switching:</strong> Switch gizmos (Move, Rotate, Scale, Bounds) at any time without losing your current selection.\n              </p>\n            </div>\n\n            <div class=\"help-section\">\n              <h4><i class=\"app-icon\" data-lucide=\"sparkles\"></i> 3D Modeling & AI Workflow Tips</h4>\n              <p style=\"font-size: 13px; color: var(--text-secondary); line-height: 1.5\">\n                • <strong>Separate Loose Parts:</strong> AI-generated meshes often merge all pieces into one mesh. Click \"Separate\" to split disconnected parts into distinct objects.<br />\n                • <strong>Merge Meshes:</strong> Combine multiple selected meshes into a single unified object while preserving all material channels.<br />\n                • <strong>Center Pivot:</strong> Click \"Center Pivot\" if gizmos appear offset from the mesh visual geometry.<br />\n                • <strong>Pick & Place:</strong> In the Tools menu, choose \"Create Mesh\" and click on any surface to spawn new primitives precisely in 3D.<br />\n                • <strong>Snapping Increments:</strong> Open the \"Scene & Environment\" tool to adjust Move Snap distance (units) and Rotate Snap angle (degrees).\n              </p>\n            </div>\n          </div>\n          <div class=\"modal-footer\">\n            <button class=\"tool-btn btn-primary\" id=\"btnHelpDone\">Got it!</button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Export Modal Dialog -->\n      <div id=\"exportModal\">\n        <div class=\"modal-content export-modal-content\">\n          <div class=\"modal-header\">\n            <h3><i class=\"app-icon\" data-lucide=\"download\"></i> Export 3D Model</h3>\n            <button class=\"dialog-btn btn-close\" id=\"btnCloseExport\" title=\"Close\"><i class=\"app-icon\" data-lucide=\"x\"></i></button>\n          </div>\n          <div class=\"modal-body export-modal-body\">\n            <div class=\"export-form-group\">\n              <label for=\"exportFilenameInput\" class=\"export-form-label\">Filename</label>\n              <div class=\"export-input-wrap\">\n                <input type=\"text\" id=\"exportFilenameInput\" class=\"export-text-input\" placeholder=\"model_name\" spellcheck=\"false\" autocomplete=\"off\" />\n                <span id=\"exportExtensionBadge\" class=\"export-ext-badge\">.glb</span>\n              </div>\n            </div>\n\n            <div class=\"export-form-group\">\n              <label class=\"export-form-label\">Format</label>\n              <div class=\"export-format-options\" id=\"exportFormatOptions\">\n                <label class=\"export-format-option active\" data-format=\"glb\">\n                  <input type=\"radio\" name=\"exportModalFormat\" value=\"glb\" checked class=\"export-radio-hidden\" />\n                  <div class=\"format-option-header\">\n                    <span class=\"format-option-name\">GLB</span>\n                    <span class=\"format-option-tag recommended\">Recommended</span>\n                  </div>\n                  <div class=\"format-option-desc\">Binary glTF 2.0 with embedded geometry, materials &amp; textures</div>\n                </label>\n\n                <label class=\"export-format-option\" data-format=\"gltf\">\n                  <input type=\"radio\" name=\"exportModalFormat\" value=\"gltf\" class=\"export-radio-hidden\" />\n                  <div class=\"format-option-header\">\n                    <span class=\"format-option-name\">glTF</span>\n                    <span class=\"format-option-tag\">JSON + Bin</span>\n                  </div>\n                  <div class=\"format-option-desc\">Standard glTF JSON scene description with external or embedded buffers</div>\n                </label>\n\n                <label class=\"export-format-option\" data-format=\"obj\">\n                  <input type=\"radio\" name=\"exportModalFormat\" value=\"obj\" class=\"export-radio-hidden\" />\n                  <div class=\"format-option-header\">\n                    <span class=\"format-option-name\">OBJ</span>\n                    <span class=\"format-option-tag\">Wavefront</span>\n                  </div>\n                  <div class=\"format-option-desc\">Universal polygon geometry format for 3D modeling &amp; DCC suites</div>\n                </label>\n\n                <label class=\"export-format-option\" data-format=\"stl\">\n                  <input type=\"radio\" name=\"exportModalFormat\" value=\"stl\" class=\"export-radio-hidden\" />\n                  <div class=\"format-option-header\">\n                    <span class=\"format-option-name\">STL</span>\n                    <span class=\"format-option-tag\">3D Print</span>\n                  </div>\n                  <div class=\"format-option-desc\">Stereolithography triangulated surface mesh for slicing &amp; 3D printing</div>\n                </label>\n              </div>\n            </div>\n\n            <div class=\"export-form-group\">\n              <label class=\"export-form-label\">Scope</label>\n              <div class=\"export-scope-box\">\n                <label class=\"export-checkbox-container\">\n                  <input type=\"checkbox\" id=\"exportSelectedOnlyCheckbox\" class=\"export-checkbox\" />\n                  <span class=\"export-checkbox-title\">Export selected objects only</span>\n                </label>\n                <div id=\"exportSelectionDetails\" class=\"export-selection-details\">\n                  All visible meshes will be exported\n                </div>\n              </div>\n            </div>\n          </div>\n          <div class=\"modal-footer export-modal-footer\">\n            <button class=\"tool-btn\" id=\"btnCancelExport\">Cancel</button>\n            <button class=\"tool-btn btn-export\" id=\"btnConfirmExport\">\n              <span class=\"btn-icon\"><i class=\"app-icon\" data-lucide=\"download\"></i></span>\n              <span class=\"btn-label\">Export</span>\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <!-- Toast Notification -->\n      <div id=\"toast\">\n        <span id=\"toastIcon\"><i class=\"app-icon\" data-lucide=\"info\"></i></span>\n        <span id=\"toastText\">Message</span>\n      </div>\n    ";
}
